/* ══════════════════════════════════════════════════════════
   1. HELPERS MATEMÁTICOS  (funciones puras, sin dependencias)
   ══════════════════════════════════════════════════════════ */
const R = (a,b) => a + Math.floor(Math.random()*(b-a+1));
const pick = a => a[Math.floor(Math.random()*a.length)];
const shuffle = a => a.map(v=>[Math.random(),v]).sort((x,y)=>x[0]-y[0]).map(x=>x[1]);

function mcd(a,b){ a=Math.abs(a); b=Math.abs(b); while(b){ const t=b; b=a%b; a=t; } return a; }
function mcm(a,b){ return Math.abs(a*b)/mcd(a,b); }
function esPrimo(n){
  if(n<2) return false;
  if(n%2===0) return n===2;
  for(let d=3; d*d<=n; d+=2) if(n%d===0) return false;
  return true;
}
function factorizar(n){
  const f={}; let d=2;
  while(d*d<=n){ while(n%d===0){ f[d]=(f[d]||0)+1; n/=d; } d++; }
  if(n>1) f[n]=(f[n]||0)+1;
  return f;
}
function simplificar(n,d){ const g=mcd(n,d)||1; return [n/g, d/g]; }
const SUP={'0':'⁰','1':'¹','2':'²','3':'³','4':'⁴','5':'⁵','6':'⁶','7':'⁷','8':'⁸','9':'⁹'};
const sup = n => String(n).split('').map(c=>SUP[c]).join('');
function fmtFactores(f){
  const ps = Object.keys(f).map(Number).sort((a,b)=>a-b);
  if(!ps.length) return '1';
  return ps.map(p => f[p]>1 ? p+sup(f[p]) : ''+p).join(' × ');
}
// dos rectas cruzadas: ∠1 = g (dado, en dorado), ∠2 = 180-g (adyacente), ∠3 = g (opuesto por el vértice)
function svgCruce(g, uid){
  const cx=150, cy=110, R=90, rArc=40, rTxt=60;
  const rad = a => a*Math.PI/180;
  const pt = (a,r) => ({ x:(cx + r*Math.cos(rad(a))).toFixed(1), y:(cy - r*Math.sin(rad(a))).toFixed(1) });
  const p0=pt(0,R), p180=pt(180,R), pg=pt(g,R), pgOp=pt(g+180,R);
  const t1=pt(g/2,rTxt), t2=pt((g+180)/2,rTxt), t3=pt(180+g/2,rTxt);
  const arc = (a1,a2) => { const q1=pt(a1,rArc), q2=pt(a2,rArc); return `M ${q1.x} ${q1.y} A ${rArc} ${rArc} 0 0 1 ${q2.x} ${q2.y}`; };
  return `<svg viewBox="0 0 300 200" style="width:100%;max-width:300px;height:auto;color:var(--texto);display:block;margin:10px auto 0" xmlns="http://www.w3.org/2000/svg">
    <defs>
      <marker id="fe${uid}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="currentColor"/></marker>
      <marker id="fs${uid}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto-start-reverse"><path d="M0,0 L8,4 L0,8 Z" fill="currentColor"/></marker>
    </defs>
    <line x1="${p180.x}" y1="${p180.y}" x2="${p0.x}" y2="${p0.y}" stroke="currentColor" stroke-width="2" marker-start="url(#fs${uid})" marker-end="url(#fe${uid})"/>
    <line x1="${pgOp.x}" y1="${pgOp.y}" x2="${pg.x}" y2="${pg.y}" stroke="currentColor" stroke-width="2" marker-start="url(#fs${uid})" marker-end="url(#fe${uid})"/>
    <path d="${arc(0,g)}" fill="none" stroke="var(--acento)" stroke-width="2"/>
    <path d="${arc(g,180)}" fill="none" stroke="currentColor" stroke-width="1.3" opacity=".55"/>
    <path d="${arc(180,180+g)}" fill="none" stroke="currentColor" stroke-width="1.3" opacity=".55"/>
    <text x="${t1.x}" y="${t1.y}" fill="var(--acento)" font-size="16" font-weight="800" text-anchor="middle" dominant-baseline="middle">${g}°</text>
    <text x="${t2.x}" y="${t2.y}" fill="currentColor" font-size="14" font-weight="700" text-anchor="middle" dominant-baseline="middle">∠2</text>
    <text x="${t3.x}" y="${t3.y}" fill="currentColor" font-size="14" font-weight="700" text-anchor="middle" dominant-baseline="middle">∠3</text>
  </svg>`;
}
// cuatro puntos que arman cometa / rectángulo / paralelogramo / trapecio, siempre dentro del mismo viewBox
function svgCuadrilatero(tipo, uid){
  const RR = (a,b) => a + Math.floor(Math.random()*(b-a+1));
  const pick2 = arr => arr[Math.floor(Math.random()*arr.length)];
  let pts;
  if(tipo==='rectangulo'){
    // a veces bien ancho, a veces bien alto, a veces casi cuadrado — todas son "Rectángulo" igual
    const w = RR(90,190), h = RR(60,150);
    const x0 = 150-w/2, y0 = 100-h/2;
    pts = [[x0,y0],[x0+w,y0],[x0+w,y0+h],[x0,y0+h]];
  } else if(tipo==='paralelogramo'){
    const w = RR(100,150), h = RR(70,110), skew = pick2([1,-1]) * RR(25,55);
    const x0 = 150 - w/2 - Math.max(skew,0)/2, y0 = 100-h/2;
    pts = [[x0+Math.max(-skew,0),y0],[x0+Math.max(-skew,0)+w,y0],[x0+Math.max(-skew,0)+w+skew,y0+h],[x0+Math.max(-skew,0)+skew,y0+h]];
  } else if(tipo==='trapecio'){
    const baseM = RR(140,190), baseCh = RR(50,90), h = RR(70,110);
    const offset = pick2(['centrado','izquierda']);
    const dx = offset==='centrado' ? (baseM-baseCh)/2 : RR(10,baseM-baseCh-10);
    const x0 = 150-baseM/2, y0 = 100-h/2;
    pts = [[x0+dx,y0],[x0+dx+baseCh,y0],[x0+baseM,y0+h],[x0,y0+h]];
  } else {   // cometa — a veces vertical (alta), a veces acostada de lado (misma figura, ejes cambiados)
    const alaX = RR(45,70), alaY = RR(40,60), colaY = RR(80,110);
    const vertical = Math.random()<0.6;
    const rel = [[0,-(alaY+15)],[alaX,0],[0,colaY-15],[-alaX,0]];   // relativo al centro (150,100)
    pts = rel.map(([dx,dy]) => vertical ? [150+dx,100+dy] : [150+dy,100+dx]);
  }
  const puntos = pts.map(p=>p.join(',')).join(' ');
  return `<svg viewBox="0 0 300 200" style="width:100%;max-width:300px;height:auto;color:var(--texto);display:block;margin:10px auto 0" xmlns="http://www.w3.org/2000/svg">
    <polygon points="${puntos}" fill="none" stroke="var(--acento)" stroke-width="2.5" stroke-linejoin="round"/>
  </svg>`;
}
// dos rectas paralelas cortadas por una transversal — para "el siguiente diagrama representa___"
function svgParalelasTransversal(uid){
  return `<svg viewBox="0 0 300 200" style="width:100%;max-width:300px;height:auto;color:var(--texto);display:block;margin:10px auto 0" xmlns="http://www.w3.org/2000/svg">
    <line x1="30" y1="60" x2="270" y2="60" stroke="currentColor" stroke-width="2"/>
    <line x1="30" y1="140" x2="270" y2="140" stroke="currentColor" stroke-width="2"/>
    <line x1="90" y1="15" x2="210" y2="185" stroke="var(--acento)" stroke-width="2"/>
  </svg>`;
}
// varias rectas saliendo del mismo punto, dentro de un mismo semiplano (para que TODOS los
// ángulos que se formen entre ellas sean, sin excepción, menores que 180°)
function svgRayos(angulos, uid){
  const ox=60, oy=180, len=170, rad = a=>a*Math.PI/180;
  const lines = angulos.map(a => {
    const x = (ox + len*Math.cos(rad(a))).toFixed(1), y = (oy - len*Math.sin(rad(a))).toFixed(1);
    return `<line x1="${ox}" y1="${oy}" x2="${x}" y2="${y}" stroke="currentColor" stroke-width="2"/>`;
  }).join('');
  return `<svg viewBox="0 0 300 200" style="width:100%;max-width:300px;height:auto;color:var(--texto);display:block;margin:10px auto 0" xmlns="http://www.w3.org/2000/svg">
    <circle cx="${ox}" cy="${oy}" r="3.5" fill="var(--acento)"/>${lines}
  </svg>`;
}
// símbolo de resistor (zigzag de 3 picos) entre dos puntos — horizontal o vertical según el eje
function zigzagV(x, y1, y2){
  const amp=9, lead=(y2-y1)*0.15, y0=y1+lead, y5=y2-lead, step=(y5-y0)/4;
  return `M ${x} ${y1} L ${x} ${y0.toFixed(1)} `+
    `L ${(x+amp).toFixed(1)} ${(y0+step).toFixed(1)} `+
    `L ${(x-amp).toFixed(1)} ${(y0+2*step).toFixed(1)} `+
    `L ${(x+amp).toFixed(1)} ${(y0+3*step).toFixed(1)} `+
    `L ${x} ${y5.toFixed(1)} L ${x} ${y2}`;
}
function zigzagH(x1, x2, y){
  const amp=9, lead=(x2-x1)*0.15, x0=x1+lead, x5=x2-lead, step=(x5-x0)/4;
  return `M ${x1} ${y} L ${x0.toFixed(1)} ${y} `+
    `L ${(x0+step).toFixed(1)} ${(y+amp).toFixed(1)} `+
    `L ${(x0+2*step).toFixed(1)} ${(y-amp).toFixed(1)} `+
    `L ${(x0+3*step).toFixed(1)} ${(y+amp).toFixed(1)} `+
    `L ${x5.toFixed(1)} ${y} L ${x2} ${y}`;
}
// símbolo de batería (pila): barra larga y delgada (+) arriba, barra corta y gruesa (−) abajo,
// insertada en el punto medio de un tramo vertical de alambre entre y1 y y2
function bateriaV(x, y1, y2){
  const midY=(y1+y2)/2;
  return `<line x1="${x}" y1="${y1}" x2="${x}" y2="${midY-8}" stroke="currentColor" stroke-width="2"/>
    <line x1="${x-12}" y1="${midY-8}" x2="${x+12}" y2="${midY-8}" stroke="currentColor" stroke-width="2"/>
    <line x1="${x-7}" y1="${midY+8}" x2="${x+7}" y2="${midY+8}" stroke="currentColor" stroke-width="5"/>
    <line x1="${x}" y1="${midY+8}" x2="${x}" y2="${y2}" stroke="currentColor" stroke-width="2"/>`;
}
// circuito de una sola malla (fuente + un resistor) — para Ley de Ohm y Ley de Watt. Cada
// etiqueta (V/R/I/P) es el texto a mostrar, o null para no dibujarla (cuando ese dato no
// aplica a la pregunta); "?" se usa para la incógnita que hay que hallar.
function svgCircuitoSimple(V, R, I, P, uid){
  const L=80, Rd=220, T=50, B=150;
  return `<svg viewBox="0 0 300 200" style="width:100%;max-width:300px;height:auto;color:var(--texto);display:block;margin:10px auto 0" xmlns="http://www.w3.org/2000/svg">
    <defs><marker id="fa${uid}" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="var(--acento)"/></marker></defs>
    <line x1="${L}" y1="${T}" x2="${Rd}" y2="${T}" stroke="currentColor" stroke-width="2"/>
    <line x1="${L}" y1="${B}" x2="${Rd}" y2="${B}" stroke="currentColor" stroke-width="2"/>
    ${bateriaV(L,T,B)}
    <path d="${zigzagV(Rd,T,B)}" fill="none" stroke="currentColor" stroke-width="2"/>
    <line x1="${L+25}" y1="${T}" x2="${L+70}" y2="${T}" stroke="var(--acento)" stroke-width="2.5" marker-end="url(#fa${uid})"/>
    ${I!=null?`<text x="${(L+Rd)/2}" y="${T-12}" fill="var(--acento)" font-size="14" font-weight="800" text-anchor="middle">I = ${I}</text>`:''}
    ${V!=null?`<text x="${L}" y="${B+26}" fill="currentColor" font-size="14" font-weight="700" text-anchor="middle">V = ${V}</text>`:''}
    ${R!=null?`<text x="${Rd}" y="${B+26}" fill="currentColor" font-size="14" font-weight="700" text-anchor="middle">R = ${R}</text>`:''}
    ${P!=null?`<text x="${(L+Rd)/2}" y="${B+26}" fill="currentColor" font-size="14" font-weight="700" text-anchor="middle">P = ${P}</text>`:''}
  </svg>`;
}
// circuito en serie: fuente + n resistores en línea sobre el alambre de arriba. opts:
// {E, It, marca} — It es el texto de la flecha de corriente (null = no mostrarla todavía,
// como cuando aún no se sabe It); marca:{idx,tipo:'V'|'P'} anota V(Ri)=? o P(Ri)=? bajo un
// resistor puntual, o marca:{tipo:'Rt'|'Pt'} anota esa incógnita cerca de la fuente.
function svgCircuitoSerie(Rs, opts, uid){
  const {E, It, marca, rIncognita} = opts;
  const nm = i => (opts.nombres||[])[i] || 'R'+(i+1);
  const n = Rs.length, L=45, Rd=335, T=55, B=170, midY=(T+B)/2;
  const topL=125, topR=325, segW=(topR-topL)/n;
  let zz='', rlabels='', extra='';
  for(let i=0;i<n;i++){
    const x1=topL+segW*i+10, x2=topL+segW*(i+1)-10, cx=(x1+x2)/2;
    zz += `<path d="${zigzagH(x1,x2,T)}" fill="none" stroke="currentColor" stroke-width="2"/>`;
    const rTxt = rIncognita===i ? `${nm(i)}=?` : `${nm(i)}=${Rs[i]}Ω`;
    // alturas alternadas: con 4-5 resistores las etiquetas vecinas ("R1=15KΩ") no caben en una sola fila
    rlabels += `<text x="${cx}" y="${T-12-(i%2)*15}" fill="${rIncognita===i?'var(--acento)':'currentColor'}" font-size="11" font-weight="700" text-anchor="middle">${rTxt}</text>`;
    if(marca && marca.idx===i) extra += `<text x="${cx}" y="${T+24}" fill="var(--acento)" font-size="12" font-weight="800" text-anchor="middle">${marca.tipo}(${nm(i)})=?</text>`;
  }
  if(marca && (marca.tipo==='Rt'||marca.tipo==='Pt'||marca.tipo==='Vt')) extra += `<text x="${(L+Rd)/2}" y="${B+40}" fill="var(--acento)" font-size="13" font-weight="800" text-anchor="middle">${marca.tipo} = ?</text>`;
  const flechaI = It!=null ? `<line x1="${L+15}" y1="${T}" x2="${topL-15}" y2="${T}" stroke="var(--acento)" stroke-width="2.5" marker-end="url(#fa${uid})"/>
    <text x="${(L+topL)/2}" y="${T-10}" fill="var(--acento)" font-size="12" font-weight="800" text-anchor="middle">It=${It}</text>` : '';
  const eLabel = E!=null ? `E=${E}` : '';
  return `<svg viewBox="0 0 360 220" style="width:100%;max-width:340px;height:auto;color:var(--texto);display:block;margin:10px auto 0" xmlns="http://www.w3.org/2000/svg">
    <defs><marker id="fa${uid}" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="var(--acento)"/></marker></defs>
    <line x1="${L}" y1="${T}" x2="${topL}" y2="${T}" stroke="currentColor" stroke-width="2"/>
    <line x1="${topR}" y1="${T}" x2="${Rd}" y2="${T}" stroke="currentColor" stroke-width="2"/>
    <line x1="${L}" y1="${B}" x2="${Rd}" y2="${B}" stroke="currentColor" stroke-width="2"/>
    <line x1="${Rd}" y1="${T}" x2="${Rd}" y2="${B}" stroke="currentColor" stroke-width="2"/>
    ${bateriaV(L,T,B)}
    ${zz}
    ${flechaI}
    ${rlabels}
    ${extra}
    <text x="${L}" y="${B+26}" fill="currentColor" font-size="12" font-weight="700" text-anchor="middle">${eLabel}</text>
  </svg>`;
}
// circuito en paralelo: fuente + n resistores como ramas verticales entre dos rieles
// horizontales. opts: {V, It, marca} — mismo esquema que svgCircuitoSerie; marca:{idx,tipo:'I'}
// anota I(Ri)=? bajo una rama puntual, marca:{tipo:'Rt'} lo anota al centro.
function svgCircuitoParalelo(Rs, opts, uid){
  const {V, It, marca} = opts;
  const nm = i => (opts.nombres||[])[i] || 'R'+(i+1);
  const n = Rs.length, L=45, Rd=335, T=55, B=175, midY=(T+B)/2;
  const branchL=130, branchR=325, segW = n>1 ? (branchR-branchL)/(n-1) : 0;
  let branches='', labels='', extra='';
  for(let i=0;i<n;i++){
    const x = n>1 ? branchL+segW*i : (branchL+branchR)/2;
    branches += `<path d="${zigzagV(x,T,B)}" fill="none" stroke="currentColor" stroke-width="2"/>`;
    labels += `<text x="${x}" y="${B+22}" fill="currentColor" font-size="11" font-weight="700" text-anchor="middle">${nm(i)}=${Rs[i]}Ω</text>`;
    if(marca && marca.idx===i) extra += `<text x="${x}" y="${B+38}" fill="var(--acento)" font-size="12" font-weight="800" text-anchor="middle">${marca.tipo||'I'}(${nm(i)})=?</text>`;
  }
  if(marca && (marca.tipo==='Rt'||marca.tipo==='Pt')) extra += `<text x="${(branchL+branchR)/2}" y="${B+38}" fill="var(--acento)" font-size="13" font-weight="800" text-anchor="middle">${marca.tipo} = ?</text>`;
  const flechaI = It!=null ? `<line x1="${L+15}" y1="${T}" x2="${branchL-15}" y2="${T}" stroke="var(--acento)" stroke-width="2.5" marker-end="url(#fa${uid})"/>
    <text x="${(L+branchL)/2}" y="${T-10}" fill="var(--acento)" font-size="12" font-weight="800" text-anchor="middle">It=${It}</text>` : '';
  const vLabel = V!=null ? `V=${V}` : (marca && marca.tipo==='Vt' ? 'Vt=?' : '');
  return `<svg viewBox="0 0 360 235" style="width:100%;max-width:340px;height:auto;color:var(--texto);display:block;margin:10px auto 0" xmlns="http://www.w3.org/2000/svg">
    <defs><marker id="fa${uid}" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="var(--acento)"/></marker></defs>
    <line x1="${L}" y1="${T}" x2="${Rd}" y2="${T}" stroke="currentColor" stroke-width="2"/>
    <line x1="${L}" y1="${B}" x2="${Rd}" y2="${B}" stroke="currentColor" stroke-width="2"/>
    ${bateriaV(L,T,B)}
    ${branches}
    ${flechaI}
    ${labels}
    ${extra}
    <text x="${L}" y="${T-14}" fill="currentColor" font-size="12" font-weight="700" text-anchor="middle">${vLabel}</text>
  </svg>`;
}
// ejercicio de circuitos tal cual lo pide la presentación: uno o varios valores en un solo
// ejercicio (tipo 'multi'), cada campo con 1% de tolerancia (el PDF redondea: 0.000470 A, 10.88 A)
// compara solo el lado derecho de la fórmula, sin fijarse en mayúsculas, espacios, ×/x/*, Ω/ft,
// "(Ley de Ohm)" ni en el subíndice t/total (Vt/Rt = V/R) — lo que importa es que sepa la fórmula
function normFormula(s){
  let t = String(s).replace(/<[^>]+>/g,'').toLowerCase()
    .replace(/\(\s*ley de (ohm|watt)\s*\)/g,'').replace(/sqrt/g,'√').replace(/\^2/g,'²')
    .replace(/÷/g,'/').replace(/[−–]/g,'-').replace(/total/g,'t').replace(/[Ωω]|ft/g,'');
  const i = t.indexOf('='); if(i >= 0) t = t.slice(i+1);
  return t.replace(/[\s×·x*]/g,'').replace(/([virp])t/g,'$1');
}
const formulaOk = (s, c) => [c.fs, ...(c.f || [])].some(x => normFormula(x) === normFormula(s));
function ejCirc(c, truco){
  const campos = c.campos.map(k => ({ et:k.et, u:k.u, ops:k.ops, fs:k.fs, sub:k.sub, f:k.f, tol: k.ops ? undefined : Math.abs(k.r)*0.01 }));
  return { enunciado: c.enun + (c.svg || ''), tipo:'multi', campos, respuesta: c.campos.map(k => k.r), sinNumeros:true,
    explicacion:[...c.pasos, `→ ${c.campos.map(k => `${k.et} = ${k.r}${k.u ? ' '+k.u : ''}`).join(', ')}`, truco] };
}
function fmtFactoresPlano(f){
  const ps = Object.keys(f).map(Number).sort((a,b)=>a-b);
  if(!ps.length) return '1';
  return ps.map(p => f[p]>1 ? p+'^'+f[p] : ''+p).join(' * ');
}
const sumaDig = n => String(n).split('').reduce((s,c)=>s + (+c), 0);
const porNivel = (nv,f,m,d) => nv==='facil' ? f : nv==='medio' ? m : d;
// el resto de la app escribe el signo menos como '−' (U+2212), pero un número negativo
// interpolado en un template (${n} con n<0) sale con el guion ASCII '-' de JS — mm() lo
// pareja donde un enunciado muestra el número crudo (no ya envuelto en su propio "− ${n}")
const mm = n => String(n).replace('-','−');
// normaliza la "parte variable" de un término (x, x^2, x², X) a una forma comparable: minúscula,
// sin espacios, sin "^", con el exponente como dígito plano — para aceptar varias formas de
// escribir lo mismo en el tipo 'coefvar'
const normVar = s => String(s).trim().toLowerCase().replace(/\s+/g,'').replace(/\^/g,'')
  .replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹]/g, c => '⁰¹²³⁴⁵⁶⁷⁸⁹'.indexOf(c));
// fracción apilada para el enunciado
const fr = (n,d) => `<span class="fr"><b>${n}</b><i>${d}</i></span>`;
// tipo 'orden' venía solo con fracciones {n,d} — otras materias ordenan texto plano (ej. épocas
// históricas), así que se acepta cualquiera de las dos formas al mostrar una opción
const _ordenLabel = f => typeof f === 'string' ? f : fr(f.n,f.d);
const _ordenTexto = f => typeof f === 'string' ? f : `${f.n}/${f.d}`;
const cmpSigno = (a,b) => a<b ? '<' : a>b ? '>' : '=';
// también escapa las comillas: se usa dentro de value="…" (nombre del grupo) y un nombre con " abría un atributo nuevo
const escHtml = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
// ── fracciones con signo (capítulo 4) ──
const frS = (n,d) => (n<0 ? '−' : '') + fr(Math.abs(n), d);        // signo delante de la fracción apilada
const frP = (n,d) => n<0 ? `(${frS(n,d)})` : frS(n,d);             // entre paréntesis si va después de un operador
const tf  = (n,d) => `${mm(n)}/${d}`;                               // texto plano para las explicaciones
const tfP = (n,d) => n<0 ? `(${tf(n,d)})` : tf(n,d);
const mixS = (e,n,d) => `${e<0?'−':''}${Math.abs(e)} ${fr(n,d)}`;
// denominadores con factores en común, para que el MCD no sea siempre el producto
const DENS_FRAC = [2,3,4,5,6,8,9,10,12,15,16,18,20,24];
function sumarF(fs){                                                // fs = [{n,d},...] → suma simplificada + pasos
  const m = fs.reduce((ac,f)=>mcm(ac,f.d), 1);
  const nums = fs.map(f => f.n*(m/f.d));
  const tot = nums.reduce((a,b)=>a+b, 0);
  const [sn,sd] = simplificar(tot, m);
  return { m, nums, tot, n:sn, d:sd };
}
function multF(fs){                                                 // producto simplificado + producto "crudo"
  let rawN = 1, rawD = 1; fs.forEach(f => { rawN *= f.n; rawD *= f.d; });
  const [n,d] = simplificar(rawN, rawD);
  return { rawN, rawD, n, d };
}
const recipF = f => ({ n: f.n<0 ? -f.d : f.d, d: Math.abs(f.n) });  // recíproco, el signo se queda arriba
const divF = (a,b) => multF([a, recipF(b)]);
const addF = (a,b) => { const r = sumarF([a,b]); return { n:r.n, d:r.d }; };
// operando "bonito": entero sin barra, fracción apilada; con paréntesis si es negativo y va tras un operador
const opS = f => f.d===1 ? mm(f.n) : frS(f.n,f.d);
const opP = f => f.n<0 ? `(${opS(f)})` : opS(f);
const opT = f => f.d===1 ? mm(f.n) : tf(f.n,f.d);
// ── pasos desglosados, para quien no sabe nada: cada operación con fracciones explicada
//    renglón por renglón (los módulos de cap. 4 los usan dentro de "Por qué") ──
// suma de dos enteros con signo, explicada con la regla de signos (como en reglas-signos)
function explSumaEnteros(a, b){
  const r = a + b;
  if(a === 0 || b === 0) return `${mm(a)} + ${b<0?`(${mm(b)})`:b} = ${mm(r)} (sumar 0 no cambia nada).`;
  if((a<0) === (b<0)) return `${mm(a)} + ${b<0?`(${mm(b)})`:b}: los dos tienen el MISMO signo, así que se SUMAN (sin los signos):<br>${Math.abs(a)} + ${Math.abs(b)} = ${Math.abs(r)}<br>Se queda ese mismo signo: ${mm(r)}`;
  const g = Math.abs(a) >= Math.abs(b) ? a : b;
  return `${mm(a)} + ${b<0?`(${mm(b)})`:b}: tienen signos DIFERENTES, así que se RESTAN (sin los signos):<br>${Math.max(Math.abs(a),Math.abs(b))} − ${Math.min(Math.abs(a),Math.abs(b))} = ${Math.abs(r)}<br>Se queda el signo del más grande (el ${mm(g)}): ${mm(r)}`;
}
// ── dibujos con flechas para las explicaciones: × al pasar a denominador común, ÷ al simplificar,
