const _sinNotasRepetidas = html => { const vistas = {}; return html.replace(/<div class="dgNota" data-k="([^"]+)">[\s\S]*?<\/div>/g, (m, k) => vistas[k] ? '' : (vistas[k] = 1, m)); };
// ── RECETA: la misma forma de explicar en todos los temas ──
// Qué te piden → pasos con título (se abren de a uno con "Siguiente paso") → Respuesta → Comprueba → Error común,
// y al final la "Receta para el examen" (los títulos de los pasos). Va como líneas con marca '§' dentro de
// explicacion, así el autotest, el ejemplo de tema y el examen siguen funcionando igual (ver explReceta).
function receta({ pide, pasos, resp, comp, error, ejemplo, truco }){
  const L = [`§pide|${pide}`];
  pasos.forEach((p, i) => L.push(`§paso|Paso ${i + 1} — ${p.t}`, ...p.l.filter(Boolean)));
  L.push(`§resp|${resp}`);
  if(comp) L.push(`§comp|${comp}`);
  if(error) L.push(`§error|${error}`);
  L.push(`TRUCO: Receta para el examen: ${pasos.map((p, i) => `${i + 1}) ${p.t}.`).join(' ')}${comp ? ` ${pasos.length + 1}) Comprueba.` : ''} Ejemplo con este mismo: ${ejemplo}`);
  if(truco) L.push(`TRUCO: ${truco}`);   // un atajo propio del ejercicio, aparte de la receta (sale en su recuadro "TRUCO PARA QUE SEA MÁS FÁCIL")
  return L;
}
// el número que cambia en cada paso, en color
const cb = s => `<b class="cambia">${s}</b>`;
// cuentas de enteros explicadas, con la regla del signo cuando hace falta (b siempre positivo)
function cuentaMas(a, b){
  // una cuenta por renglón (<br>): así no queda todo pegado
  if(a >= 0) return b >= 10 && b % 10 && a >= 10 ? `${a} + ${b}, por partes:<br>${a} + ${b - b%10} = ${a + b - b%10}<br>${a + b - b%10} + ${b%10} = ${a + b}` : `${a} + ${b} = ${a + b}`;
  const A = -a;
  if(A === b) return `${mm(a)} + ${b}: son opuestos, se cancelan → 0`;
  return A > b ? `${mm(a)} + ${b}: tienen signos diferentes, así que se RESTAN (sin los signos):<br>${A} − ${b} = ${A - b}<br>Se queda el signo del más grande (el ${mm(a)}): ${mm(a + b)}`
               : `${mm(a)} + ${b}: tienen signos diferentes, así que se RESTAN (sin los signos):<br>${b} − ${A} = ${b - A}<br>Se queda el signo del más grande (el +${b}): ${a + b}`;
}
function cuentaMenos(a, b){
  if(a >= b) return b >= 10 && b % 10 && a >= 20 ? `${a} − ${b}, por partes:<br>${a} − ${b - b%10} = ${a - b + b%10}<br>${a - b + b%10} − ${b%10} = ${a - b}` : `${a} − ${b} = ${a - b}`;
  if(a >= 0) return `${a} − ${b}: le quitas MÁS de lo que tienes, así que el resultado es negativo.<br>Se resta el grande menos el chico: ${b} − ${a} = ${b - a}<br>Y se le pone el signo menos: ${mm(a - b)}`;
  return `${mm(a)} − ${b}: ya está debajo del 0 y baja ${b} más.<br>Se suman sin el signo: ${-a} + ${b} = ${b - a}<br>Y se le pone el signo menos: ${mm(a - b)}`;
}
// a × b en pedazos cuando las dos tienen 2 cifras o más (23 × 14 → 23 × 10 + 23 × 4)
const porPedazos = (a, b) => { if(b < 10 && a >= 10) [a, b] = [b, a];   // el chico adelante: 9 × 28 → 9 × 20 y 9 × 8
  const d = b - b%10, u = b%10;
  return b < 10 || !u ? `${a} × ${b} = ${a*b}` : `${a} × ${b}, por pedazos:<br>${a} × ${d} = ${a*d}<br>${a} × ${u} = ${a*u}<br>${a*d} + ${a*u} = ${a*b}`; };
// suma de varios números de dos en dos: 58 + 54 = 112 → 112 + 56 = 168 → …
const sumaLista = xs => { let s = xs[0]; const p = []; for(let i = 1; i < xs.length; i++){ p.push(`${s} + ${xs[i]} = ${s + xs[i]}`); s += xs[i]; } return p.join(' → '); };
// k × 3.14 en pedazos: k × 3 y k × 0.14
const por314 = k => { const r = v => Math.round(v*100)/100; return `${k} × 3.14 → ${k} × 3 = ${3*k}, y ${k} × 0.14 = ${r(0.14*k)} → ${3*k} + ${r(0.14*k)} = ${r(3.14*k)}`; };
// suma de dos enteros: normal si los dos son positivos, con la regla del signo si hay negativos
const sumaArriba = (a, b) => a >= 0 && b >= 0 ? cuentaMas(a, b) : explSumaEnteros(a, b);
const cuentaDiv = (a, b) => a < 0 ? `${mm(a)} ÷ ${b}: negativo entre positivo da negativo. ${-a} ÷ ${b} = ${-a / b} → ${mm(a / b)}` : `${a} ÷ ${b} = ${a / b}`;
const cuentaPor = (a, b) => a < 0 ? `${mm(a)} × ${b}: negativo por positivo da negativo. ${-a} × ${b} = ${-a * b} → ${mm(a * b)}` : `${a} × ${b} = ${a * b}`;
// recíproco: la fracción se voltea (flecha)
const diagRec = (n, d, rn, rd) => _nota(diagFrac([_fT(n, d), _op('→'), _fT(rn, rd)], [{ de:[0,'n'], a:[2,'n'], txt:'se voltea' }]), `Lo de arriba (${Math.abs(n)}) pasa abajo y lo de abajo (${d}) pasa arriba. El signo se queda.`);
// impropia → mixto: se divide el de arriba entre el de abajo
const diagAMixto = (imp, d, e, n) => _nota(diagFrac([_fT(imp, d), _op('='), { t:'m', e:String(e), n:n, d:d }], [{ de:[0,'n'], a:[2,'e'], txt:`${imp} ÷ ${d}` }]), `${imp} ÷ ${d} da ${e} (el entero) y sobran ${n}: ese ${n} va arriba de la fracción. El de abajo se queda igual.`);
// línea de 0° a 90° (c) o a 180° (s): el ángulo desde el 0 y una flecha a lo que le falta
