function valorExpr(s, env){
  const t = String(s).toLowerCase().replace(/−/g,'-').replace(/[×·]/g,'*').replace(/÷/g,'/')
    .replace(/²/g,'^2').replace(/³/g,'^3').replace(/\s+/g,'');
  if(!t || /[^0-9a-z.+\-*/^()]/.test(t)) return NaN;
  let i = 0;
  const atom = () => {
    if(t[i]==='('){ i++; const v = expr(); if(t[i++]!==')') throw 0; return v; }
    if(/[a-z]/.test(t[i]||'')){ const L = t[i++]; if(!(L in env)) throw 0; return env[L]; }
    const m = /^\d+(\.\d+)?/.exec(t.slice(i)); if(!m) throw 0; i += m[0].length; return +m[0];
  };
  const pot = () => { const b = atom(); if(t[i]==='^'){ i++; return b ** un(); } return b; };
  const un = () => t[i]==='-' ? (i++, -un()) : t[i]==='+' ? (i++, un()) : pot();
  const grupo = () => { let v = un(); while(i < t.length && /[0-9a-z(]/.test(t[i])) v *= pot(); return v; };
  const term = () => { let v = grupo(); while(t[i]==='*' || t[i]==='/'){ const op = t[i++], w = grupo(); v = op==='*' ? v*w : v/w; } return v; };
  function expr(){ let v = term(); while(t[i]==='+' || t[i]==='-'){ const op = t[i++], w = term(); v = op==='+' ? v+w : v-w; } return v; }
  try { const v = expr(); return i===t.length ? v : NaN; } catch(e){ return NaN; }
}
