    const pVR = (c,i) => [`${String.fromCharCode(97+i)}. V${s('R'+(i+1))} = I${s('T')} R${i+1} (Ley de Ohm)`, `V${s('R'+(i+1))} = ${c.ItS} x ${c.Rohm[i]}`, `V${s('R'+(i+1))} = ${c.VR[i]}`];
    const pPR = (c,i) => [`${String.fromCharCode(97+i)}. P${s('R'+(i+1))} = V${s('R'+(i+1))} I${s('T')} (Ley de Watt)`, `P${s('R'+(i+1))} = ${c.VR[i]} x ${c.ItS}`, `P${s('R'+(i+1))} = ${c.PR[i]}`];
