    + _gt(x0 + w - 38, y0 + h - 16, '½', 'middle', _GN, 24) + _gt(x0 + 42, y0 + 34, 'la otra', 'middle', 'currentColor', 12) + _gt(x0 + 42, y0 + 50, 'mitad', 'middle', 'currentColor', 12)
    + _gt(x0 + w/2, y0 + h + 22, bt) + _gt(x0 + w + 8, y0 + h/2 + 5, ht, 'start');
