      const rc = dN(tasa / 100), b = dN(1 + rc), pw = dN(Math.pow(b, t)), Pr = dN(P * rc), Cx = dN(P * pw);
      enun = `Halla la diferencia entre el interés compuesto anual y el interés simple sobre $${miles(P)} por ${t} años al ${fd(tasa)}% por año.`;
      pasos = [{ t:'Pasa la tasa a decimal (r)', l:[pctDec(tasa)] },
        { t:'Interés simple: I = P × r × t', l:[`P × r = ${miles(P)} × ${fd(rc)} = ${fd(Pr)} (lo que gana en 1 año)`, `× ${t} años: ${fd(Pr)} × ${t} = ${din2(Is)}`] },
        { t:'Compuesto anual: C = P(1 + r)<sup>t</sup>', l:[`1 + ${fd(rc)} = ${fd(b)}`, `${fd(b)}<sup>${t}</sup> = ${Array(t).fill(fd(b)).join(' × ')} = ${fd(pw)}`,
          `C = ${miles(P)} × ${fd(pw)} = ${fd(Cx)}`, ...(lugares(Cx) > 2 ? explRed(Cx, 2) : [])] },
        { t:'Interés compuesto = cantidad − principal', l:[`${fd(Cc)} − ${miles(P)} = ${din2(Ic)}`] },
        { t:'La diferencia: compuesto − simple', l:[`${fd(Ic)} − ${fd(Is)} = ${cb(din2(r))}`] }];
