// todo módulo sin "clase" explícita es de matemáticas — así los módulos de Álgebra de arriba no
// necesitan tocarse uno por uno al agregar otras materias
MODULOS.forEach(m => { if(!m.clase) m.clase = 'mate'; });
// etiqueta de cada tema de Álgebra en la lista de Temas (misma burbuja que Repaso de ayudante): EducoSoft | del libro | al azar. "Al azar" solo la lleva un tema que
// se repite (otro tema fijo lo copia: `cubre`); un tema con una sola versión no lleva etiqueta.
const _cubiertos = new Set(MODULOS.flatMap(m => m.cubre || []));
MODULOS.forEach(m => { if(m.clase === 'mate'){ m.tag = /^educo-/.test(m.id) ? 'educo' : /^(libro|repaso|autoeval)-/.test(m.id) ? 'libro' : _cubiertos.has(m.id) ? 'azar' : '';
  m.rep = m.tag === 'azar' || !!m.cubre; } });   // "Se repite": el tema al azar que otro tema fijo copia, y esos fijos (los "— EducoSoft")
// cada grupo de temas que se repiten (un tema al azar y sus versiones fijas, aunque estén en otro capítulo) lleva SU color en la etiqueta: _raiz junta los que se copian entre sí
const _COLORES_GRUPO = ['#1565c0', '#c62828', '#7b1fa2', '#00897b', '#d81b60', '#6d4c41', '#3949ab', '#00acc1', '#546e7a'];
const _raizDe = {}, _colorDe = {};
const _raiz = id => { if(_raizDe[id] === undefined) _raizDe[id] = id; return _raizDe[id] === id ? id : (_raizDe[id] = _raiz(_raizDe[id])); };
MODULOS.forEach(m => (m.cubre || []).forEach(t => { _raizDe[_raiz(m.id)] = _raiz(t); }));
MODULOS.forEach(m => { if(m.rep){ const r = _raiz(m.id); if(!_colorDe[r]) _colorDe[r] = _COLORES_GRUPO[Object.keys(_colorDe).length % _COLORES_GRUPO.length]; m.gc = _colorDe[r]; } });
const MOD_POR_ID = {}; MODULOS.forEach(m => MOD_POR_ID[m.id] = m);
// "Se repite" con la otra versión en OTRO capítulo (en el mismo van pegadas y no hace falta): dice dónde está. Un tema al azar apunta a su versión de EducoSoft y al revés.
const _otroLado = m => {
  if(!m.rep) return '';
  const cap = x => x.secciones[0][0], corto = x => x.nombre.replace(/ — EducoSoft.*$/, '').replace(/ \(.*$/, ''), porCap = {};
  MODULOS.filter(x => x.rep && x.tag !== m.tag && _raiz(x.id) === _raiz(m.id) && cap(x) !== cap(m)).forEach(x => (porCap[cap(x)] = porCap[cap(x)] || []).push(corto(x)));
  const lista = Object.keys(porCap).sort().map(c => `capítulo ${c} (${porCap[c].join(', ')})`);
  return lista.length ? (m.tag === 'azar' ? 'También de EducoSoft: ' : 'También al azar: ') + lista.join('; ') : '';
};
// Álgebra: los temas que todavía arman la explicación con líneas sueltas salen igual en forma de receta (aReceta)
MODULOS.filter(m => !m.clase || m.clase === 'mate').forEach(m => { const g = m.gen;
  m.gen = function(nv){ const e = g.call(this, nv);
    if(e && Array.isArray(e.explicacion) && !e.explicacion.some(l => typeof l === 'string' && l.startsWith('§'))) e.explicacion = aReceta(e.explicacion, e.enunciado);
    return e; }; });
// registro de materias — cada una con su nombre, sus "capítulos" (mismo mecanismo de
// secciones[0][0]===cap que ya usan construirCola/pantallaTemas) y el nombre de
// cada capítulo para el encabezado (si falta, se usa "Capítulo N")
const MATERIAS = {
  mate: { nombre:'Álgebra', caps:[1,2,3,4,5,6,7,8] },
  wc:   { nombre:'World Culture I', caps:[1,2,3],
          capNombre:{1:'Conceptos básicos', 2:'Orígenes del ser humano', 3:'La Prehistoria'} },
  circ: { nombre:'Circuitos Eléctricos', caps:[1,2],
          capNombre:{1:'Fundamentos Eléctricos', 2:'Circuitos en Serie y Paralelo'} },
  ayud: { nombre:'Repaso de ayudante', caps:[1,2,3,4],
          capNombre:{1:'Ley de Ohm y electricidad básica', 2:'Materiales y su uso', 3:'Las Leyes', 4:'Reglamentos (NEC y AEE)'} }
};
function nombreCapitulo(cap){
  const m = MATERIAS[materia];
  return (m.capNombre && m.capNombre[cap]) || `Capítulo ${cap}`;
}
// grupos guardados que pertenecen a la materia actual (un grupo es "de" la materia de su primer
// módulo — todos sus módulos son siempre de la misma materia, se arman desde _bloquesCapitulos
// que ya filtra por materia)
const gruposMateria = () => grupos.filter(g => g.mods.length && MOD_POR_ID[g.mods[0]] && MOD_POR_ID[g.mods[0]].clase === materia);
// mismo filtro para `errores` — "Repasar mis errores" solo debe mostrar (y consumir) los de la
// materia activa, aunque `errores` guarda las de TODAS las materias juntas en una sola lista
const erroresMateria = () => errores.filter(e => MOD_POR_ID[e.modId] && MOD_POR_ID[e.modId].clase === materia);

/* ══════════════════════════════════════════════════════════
   4. VERIFICACIÓN  — una función para los 8 tipos de entrada
   ══════════════════════════════════════════════════════════ */
function parseFactores(s){
  s = String(s).toLowerCase().replace(/[×·]/g,'*').replace(/\s+/g,'').replace(/x/g,'*');
  if(!s) return null;
  const out = {};
  for(const t of s.split('*')){
    if(!t) return null;
    const m = t.match(/^(\d+)(?:\^(\d+))?$/);
    if(!m) return null;
    const p = +m[1], e = m[2] ? +m[2] : 1;
    if(p < 2) return null;
    out[p] = (out[p]||0) + e;
  }
  return out;
}
// 1,250 = 1250 (en Puerto Rico la coma separa los miles); 2,5 sigue siendo 2.5; 0,375 = 0.375 (un número que empieza en 0 no lleva miles); el menos largo (−) también vale
const numLimpio = s => { const t = String(s).trim().replace(/\s+/g,'').replace(/[−–]/g,'-');
  return Number(/^-?[1-9]\d{0,2}(,\d{3})+(\.\d+)?$/.test(t) ? t.replace(/,/g,'') : t.replace(',','.')); };

function verificar(ej, ent){
  switch(ej.tipo){
    case 'sino': return { ok: ent === ej.respuesta };
    case 'cmp':  return { ok: ent === ej.respuesta };
    case 'num': {
      if(ej.dinero){   // dinero (EducoSoft): se acepta el $, pero el signo va ANTES del $ (−$6,072.31); "$−6,072.31" EducoSoft lo marca mal
        const s = String(ent).replace(/\s+/g,'').replace(/[−–]/g,'-');
        if(/^\$-/.test(s)) return Math.abs(numLimpio(s.slice(1)) - ej.respuesta) < (ej.tol ?? 0.01)
          ? { ok:false, incompleto:true, msg:`El número está bien, pero el signo va ANTES del $: ${din$(ej.respuesta)}. EducoSoft marca mal "$−…" (te pasó en el Quiz 7.1–7.2).` } : { ok:false };
        ent = s.replace(/^(-?)\$/, '$1');
      }
      const v = numLimpio(ent);
      if(String(ent).trim() === '') return { ok:false, vacio:true };
      if(!isFinite(v)) return { ok:false, aviso:true, msg: /\//.test(ent) ? 'Aquí va un número, no una fracción: escríbelo con punto decimal (por ejemplo 1/2 = 0.5).' : 'Eso no es un número. Escribe solo el número (por ejemplo -12 o 3.5).' };
      const tol = ej.tol ?? 0.01, ok = Math.abs(v - ej.respuesta) < tol;   // tolerancia: promedio/círculo redondean a 2 decimales; circuitos traen su propia tol (valores de 0.000470 A)
      // "2,375" se lee como 2375 (la coma separa los miles): si con punto sí sería la respuesta, se avisa en vez de contarlo como error
      const t = String(ent).trim().replace(/\s+/g,'').replace(/[−–]/g,'-');
      if(!ok && /^-?[1-9]\d{0,2},\d{3}$/.test(t) && Math.abs(Number(t.replace(',','.')) - ej.respuesta) < tol)
        return { ok:false, aviso:true, msg:`En esta app la coma separa los miles (1,250 = 1250). Para el decimal escribe el punto: ${t.replace(',','.')}.` };
      return { ok };
    }
    case 'opciones': return { ok: ent === ej.respuesta };
    case 'orden': return { ok: ent.length===ej.respuesta.length && ent.every((v,i)=>v===ej.respuesta[i]) };
    case 'frac': {
      let n = numLimpio(ent.n), d = numLimpio(ent.d);
      if(!isFinite(n) || !isFinite(d) || ent.n==='' || ent.d==='') return { ok:false, vacio:true };
      if(d === 0) return { ok:false, msg:'El denominador no puede ser 0.' };
      if(d < 0){ n = -n; d = -d; }                       // signo delante = signo arriba
      const Rp = ej.respuesta;
      if(n*Rp.d !== Rp.n*d) return { ok:false };
      if(ej.pedirSimple && mcd(Math.abs(n), d) !== 1)
        return { ok:false, incompleto:true,
                 msg:`${n}/${d} vale lo mismo, pero el ejercicio pedía la mínima expresión.` };
      return { ok:true };
    }
    case 'mixto': {
      const e = numLimpio(ent.e), n = numLimpio(ent.n), d = numLimpio(ent.d);
      if(![e,n,d].every(isFinite) || ent.e==='' || ent.n==='' || ent.d==='') return { ok:false, vacio:true };
      if(d <= 0) return { ok:false, msg:'El denominador tiene que ser mayor que 0.' };
      const Rp = ej.respuesta;
      // −2 2/7 es −(2 + 2/7): el signo del entero afecta a TODO el número, no solo al entero
      const neg = /^\s*[-−]/.test(ent.e), val = (neg ? -1 : 1) * (Math.abs(e)*d + n), valR = (Rp.e < 0 ? -1 : 1) * (Math.abs(Rp.e)*Rp.d + Rp.n);
      if(val*Rp.d !== valR*d) return { ok:false };
      if(n >= d) return { ok:false, incompleto:true,
        msg:'El valor es correcto, pero en un número mixto el numerador tiene que ser menor que el denominador.' };
      if(mcd(n,d) !== 1) return { ok:false, incompleto:true, msg:'Falta simplificar la parte fraccionaria.' };
      return { ok:true };
    }
    case 'multi': {
      // un ejercicio de la presentación que pide varios valores a la vez (ej. "Calcule Rtotal, Itotal y VR1,VR2,VR3")
      // circuitos: la fórmula (ent.f) es OPCIONAL — si la dejó en blanco no se revisa; si la
      // escribió, se le dice si está bien o mal escrita (y una mal escrita cuenta como error)
      const fs = ent.f || [];
      if(ent.some(v => String(v).trim() === '')) return { ok:false, vacio:true };
      if(ej.pares){   // pares de ángulos (casillas de 2 en 2): los pares en cualquier orden, y ∠AOC = ∠COA
        const ang = s => { const t = String(s).toUpperCase().replace(/[^A-Z]/g, ''); return t.length === 3 ? [t, [...t].reverse().join('')].sort()[0] : t; };
        const par = (a, b) => [ang(a), ang(b)].sort().join('|');
        const dados = ej.pares.map((_, k) => par(ent[2*k], ent[2*k+1])).sort(), bien = ej.pares.map(p => par(...p)).sort();
        const nBien = dados.filter(d => bien.includes(d)).length;
        return nBien === bien.length ? { ok:true } : { ok:false, incompleto: nBien > 0, msg:`Tienes ${nBien} de ${bien.length} pares bien.` };
      }
      const mal = [], fBien = [], fMal = [];
      ej.campos.forEach((c,i) => {
        if(c.ops){ if(ent[i] !== ej.respuesta[i]) mal.push(c.et); return; }
        if(c.q){   // valor exacto (Repaso/Autoevaluación del cap. 5): "7/50", "3 8/9", "-54"
          const v = leerQ(ent[i]);
          if(!v || v.d <= 0 || v.n*c.q.d !== c.q.n*v.d) mal.push(c.et);
          else if(v.d !== 1 && (mcd(v.fn, v.d) !== 1 || (v.mixto && v.fn >= v.d))) mal.push(`${c.et} (falta simplificar)`);
          return;
        }
        if(c.ex){   // con letras (Repaso/Autoevaluación del cap. 4): se compara sustituyendo valores
          const s = String(ent[i]).toLowerCase().replace(/\s+/g,'');
          if(!(c.ex === 'No definido' ? NO_DEF.test(s) : !NO_DEF.test(s) && mismaExpr(ent[i], c.ex))) mal.push(c.et);
          return;
        }
        const escrita = c.fs && String(fs[i] || '').trim() !== '';
        const malF = escrita && !formulaOk(fs[i], c);
        if(escrita) (malF ? fMal : fBien).push(c.et);
        const vIn = c.din ? Number(String(ent[i]).replace(/[\s$,]/g, '').replace('−', '-')) : numLimpio(ent[i]);   // dinero: "-$32,585" vale
        const malR = !(Math.abs(vIn - ej.respuesta[i]) < (c.tol ?? 0.01));
        if(malF || malR) mal.push(`${c.et} (${[malF && 'fórmula', malR && 'resultado'].filter(Boolean).join(' y ')})`);
      });
      const notaF = [fBien.length && `✓ Fórmulas bien escritas: ${fBien.join(', ')}.`,
                     fMal.length && `✗ Fórmulas mal escritas: ${fMal.join(', ')}.`].filter(Boolean).join('<br>');
      if(!mal.length) return notaF ? { ok:true, msg:notaF } : { ok:true };
      return { ok:false, incompleto: mal.length < ej.campos.length,
        msg:`Tienes ${ej.campos.length-mal.length} de ${ej.campos.length} bien. Revisa: ${mal.join(', ')}.${notaF ? '<br>'+notaF : ''}` };
    }
    case 'angulo2': {
      const a = numLimpio(ent.a), b = numLimpio(ent.b);
      if(!isFinite(a) || !isFinite(b) || ent.a==='' || ent.b==='') return { ok:false, vacio:true };
      return { ok: a === ej.respuesta.a && b === ej.respuesta.b };
    }
    case 'basexp': {
      const b = numLimpio(ent.b), e = numLimpio(ent.e), v = numLimpio(ent.v);
      if(![b,e,v].every(isFinite) || ent.b==='' || ent.e==='' || ent.v==='') return { ok:false, vacio:true };
      return { ok: b === ej.respuesta.b && e === ej.respuesta.e && v === ej.respuesta.v };
    }
    case 'coefvar': {
      const c = numLimpio(ent.coef);
      if(!isFinite(c) || ent.coef==='' || String(ent.variable||'').trim()==='') return { ok:false, vacio:true };
      return { ok: c === ej.respuesta.coef && normVar(ent.variable) === ej.respuesta.variable };
    }
    case 'texto': {
      const f = parseFactores(ent);
      if(!f) return { ok:false, msg:'No entendí lo que escribiste. Ejemplo: <b>2^3 * 5</b>' };
      const bases = Object.keys(f).map(Number);
      if(bases.some(p => !esPrimo(p)))
        return { ok:false, msg:`Todos los factores tienen que ser primos (${bases.filter(p=>!esPrimo(p)).join(', ')} no lo ${bases.filter(p=>!esPrimo(p)).length>1?'son':'es'}).` };
      const Rp = ej.respuesta, ks = Object.keys(Rp);
      const ok = bases.length===ks.length && ks.every(p => f[p] === Rp[p]);
      return { ok };
    }
  }
  return { ok:false };
}

// respuesta correcta con la forma que tendría escrita el usuario (lo usa autotest)
function respuestaComoEntrada(ej){
  switch(ej.tipo){
    case 'sino': case 'cmp': case 'orden': case 'opciones': return ej.respuesta;
    case 'num':   return String(ej.respuesta);
    case 'frac':  return { n:String(ej.respuesta.n), d:String(ej.respuesta.d) };
    case 'mixto': return { e:String(ej.respuesta.e), n:String(ej.respuesta.n), d:String(ej.respuesta.d) };
    case 'angulo2': return { a:String(ej.respuesta.a), b:String(ej.respuesta.b) };
    case 'multi': return Object.assign(ej.respuesta.map(String), { f: ej.campos.map(c => c.fs || '') });
    case 'basexp': return { b:String(ej.respuesta.b), e:String(ej.respuesta.e), v:String(ej.respuesta.v) };
    case 'coefvar': return { coef:String(ej.respuesta.coef), variable:ej.respuesta.variable };
    case 'texto': return fmtFactoresPlano(ej.respuesta);
  }
}
function fmtRespuesta(ej){
  switch(ej.tipo){
    case 'sino':  return ej.respuesta ? 'Sí' : 'No';
    case 'cmp':   return ej.respuesta;
    case 'num':   return String(ej.respuesta);
    case 'frac':  return `${ej.respuesta.n}/${ej.respuesta.d}`;
    case 'mixto': return `${ej.respuesta.e} ${ej.respuesta.n}/${ej.respuesta.d}`;
    case 'angulo2': return ej.etiquetas
      ? `${ej.etiquetas[0]} = ${ej.respuesta.a}, ${ej.etiquetas[1]} = ${ej.respuesta.b}`
      : `∠2 = ${ej.respuesta.a}°, ∠3 = ${ej.respuesta.b}°`;
    case 'multi': return ej.campos.some(c => c.fs)
      ? ej.campos.map((c,i) => c.fs ? `<br>${c.et}: ${c.fs} → ${c.sub} → ${ej.respuesta[i]}${c.u ? ' '+c.u : ''}` : `<br>${c.et}: ${ej.respuesta[i]}`).join('')
      : ej.campos.map((c,i) => `${c.et} = ${c.u === '$' ? '$' + fd(ej.respuesta[i], 2) : ej.respuesta[i] + (c.u ? ' '+c.u : '')}`).join(', ');
    case 'basexp': return `Base = ${ej.respuesta.b}, Exponente = ${ej.respuesta.e}, Valor = ${ej.respuesta.v}`;
    case 'coefvar': return `Coeficiente = ${ej.respuesta.coef}, Variable = ${ej.respuesta.variable}`;
    case 'texto': return fmtFactores(ej.respuesta);
    case 'orden': return ej.respuesta.map(i=>_ordenTexto(ej.opciones[i])).join(' , ');
    case 'opciones': return ej.respuesta;
  }
}

