function analizarTexto(txt){
  const t = ' ' + String(txt).toLowerCase().replace(/\s+/g,' ') + ' ';
  const puntos = {}, secs = new Set();
  // SECMAP/CLAVES son propios de Álgebra — al pegar texto de otra materia, esto solo compara
  // contra SUS módulos (y CLAVES puede faltar para ellos, de ahí el ||[] más abajo)
  const msMateria = MODULOS.filter(m => m.clase === materia);
  msMateria.forEach(m => puntos[m.id] = 0);

  // (a) rangos "3.1 - 3.8" y "3.1 a 3.8"
  const rangos = t.match(/(\d+)\s*\.\s*(\d+)\s*(?:-|–|—|a|to)\s*(\d+)\s*\.\s*(\d+)/g) || [];
  rangos.forEach(r=>{
    const m = r.match(/(\d+)\s*\.\s*(\d+)\s*(?:-|–|—|a|to)\s*(\d+)\s*\.\s*(\d+)/);
    if(+m[1] !== +m[3]) return;                          // solo dentro del mismo capítulo
    for(let s = +m[2]; s <= +m[4]; s++) secs.add(`${+m[1]}.${s}`);
  });
  // (b) secciones sueltas — solo cuentan las que existen en el mapa
  (t.match(/\b\d+\s*\.\s*\d+\b/g) || []).forEach(s => {
    const k = s.replace(/\s+/g,'');
    if(SECMAP[k]) secs.add(k);
  });

  const secsValidas = [...secs].filter(s => SECMAP[s]).sort();
  secsValidas.forEach(s => SECMAP[s].forEach(id => puntos[id] += 5));

  // (c) palabras clave — límite de palabra en LOS DOS lados, no solo uno. Con solo un lado
  // (como antes: " k" O "k "), una clave corta como "rate" hacía match dentro de "corporate ",
  // o "order" dentro de "disorder" — bastaba con que un solo extremo tuviera espacio.
  const encontradas = {};
  msMateria.forEach(m=>{
    encontradas[m.id] = [];
    (CLAVES[m.id] || []).forEach(k=>{
      const re = new RegExp('(?:^|[^a-záéíóúñ0-9])' + k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&') + '(?:$|[^a-záéíóúñ0-9])');
      if(re.test(t)){
        puntos[m.id] += 1; encontradas[m.id].push(k);
      }
    });
  });

  const detectados = msMateria.filter(m => puntos[m.id] > 0)
    .sort((a,b) => puntos[b.id] - puntos[a.id]);
  return { puntos, secciones: secsValidas, detectados, claves: encontradas };
}

/* --- lectura de archivos (las librerías se cargan solo si hacen falta) --- */
const URL_JSZIP = 'https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js';
const URL_PDFJS = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';
const URL_PDFWK = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';

// huella (SRI) de cada librería de afuera: si el CDN sirviera una copia alterada, el navegador no la corre.
// Si subes la versión de una librería, saca la huella nueva: curl -s URL | openssl dgst -sha384 -binary | openssl base64 -A
const SRI = {
  'https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js': 'sha384-+mbV2IY1Zk/X1p/nWllGySJSUN8uMs+gUAN10Or95UBH0fpj6GfKgPmgC5EXieXG',
  'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js': 'sha384-/1qUCSGwTur9vjf/z9lmu/eCUYbpOTgSjmpbMQZ1/CtX2v/WcAIKqRv+U1DUCG6e',
  'https://www.gstatic.com/firebasejs/10.14.1/firebase-app-compat.js': 'sha384-ZaR6mWzmJtrRibZ1Vm7SoHFr8OXjyAuGAXalGDKqbxFT18oi/z+oZLIRFkpeNor1',
  'https://www.gstatic.com/firebasejs/10.14.1/firebase-firestore-compat.js': 'sha384-Ke0FJhH7LyRqDxZ0wt+/OXV38yfQVu7g9VPEEGjYmB4RVOY/ta04uecRhsMwT7V3'
};
// una sola promesa por librería: si se pide dos veces seguidas (dos archivos soltados rápido),
// la segunda espera a que la primera TERMINE de cargar en vez de seguir antes de tiempo
const _cargando = {};
function cargarScript(src){
  if(_cargando[src]) return _cargando[src];
  return _cargando[src] = new Promise((ok, err)=>{
    const s = document.createElement('script');
    s.src = src;
    if(SRI[src]){ s.integrity = SRI[src]; s.crossOrigin = 'anonymous'; }
    s.onload = ()=>ok();
    s.onerror = ()=>{ delete _cargando[src]; s.remove(); err(new Error('No se pudo cargar la librería. ¿Hay internet?')); };
    document.head.appendChild(s);
  });
}
const desXml = s => s.replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"')
                     .replace(/&apos;/g,"'").replace(/&amp;/g,'&');

async function textoDePptx(file){
  await cargarScript(URL_JSZIP);
  const zip = await JSZip.loadAsync(file);
  const slides = Object.keys(zip.files)
    .filter(n => /^ppt\/(slides|notesSlides)\/\w+\d+\.xml$/.test(n))
    .sort((a,b) => (+a.replace(/\D/g,'')) - (+b.replace(/\D/g,'')));
  if(!slides.length) throw new Error('Ese .pptx no tiene diapositivas legibles.');
  const out = [];
  for(const n of slides){
    const xml = await zip.files[n].async('string');
    out.push((xml.match(/<a:t[^>]*>[\s\S]*?<\/a:t>/g) || [])
      .map(t => desXml(t.replace(/<[^>]+>/g,''))).join(' '));
  }
  return out.join('\n');
}
async function textoDePdf(file){
  await cargarScript(URL_PDFJS);
  pdfjsLib.GlobalWorkerOptions.workerSrc = URL_PDFWK;
  const doc = await pdfjsLib.getDocument({ data: await file.arrayBuffer(), isEvalSupported: false }).promise;   // isEvalSupported:false cierra la falla CVE-2024-4367 de pdf.js 3.x
  const out = [];
  for(let i=1; i<=doc.numPages; i++){
    const tc = await (await doc.getPage(i)).getTextContent();
    out.push(tc.items.map(it => it.str).join(' '));
  }
  return out.join('\n');
}
async function textoDeArchivo(file){
  const n = file.name.toLowerCase();
  if(n.endsWith('.pptx')) return textoDePptx(file);
  if(n.endsWith('.pdf'))  return textoDePdf(file);
  return file.text();
}

/* ══════════════════════════════════════════════════════════
   6. ALMACENAMIENTO
   ══════════════════════════════════════════════════════════ */
// Las 4 apps comparten el mismo espacio del navegador: si se llena, antes Mate dejaba de guardar sin decir nada. Ahora, si lo que no cabe es progreso
// de verdad, primero se suelta lo único desechable (la ronda en curso, que solo sirve para retomarla) y se reintenta; si aun así no cabe, se avisa UNA vez.
let _avisoEspacioDado = false;
function _sinEspacio(){
  if(_avisoEspacioDado) return;
  _avisoEspacioDado = true;
  avisar('No hay espacio para guardar tu progreso en este aparato (el espacio del navegador está lleno). Exporta un respaldo en Ajustes → Exportar respaldo y libera espacio borrando datos de sitios que no uses.');
}
const guardar = (k,v) => {
  const s = JSON.stringify(v);
  try{ localStorage.setItem(k, s); return; }catch(e){}
  if(!/^mate_sesion/.test(k)){
    try{ Object.keys(localStorage).filter(x => x.startsWith('mate_sesion')).forEach(x => localStorage.removeItem(x)); localStorage.setItem(k, s); return; }catch(e){}
    _sinEspacio();
  }
};
const leer = (k,d) => { try{ const v = localStorage.getItem(k); return v==null ? d : JSON.parse(v); }catch(e){ return d; } };
// fecha del CALENDARIO LOCAL, no UTC — toISOString() usa Greenwich, así que cualquier práctica
// después de las 8 pm (Puerto Rico, UTC-4) se anotaba en el día siguiente: el heatmap de
// "Últimos 14 días" pintaba la barra equivocada y la racha de días se rompía a media noche
// local en vez de a media noche real. Mismo patrón que localDateStr() en Fit-F.
const fechaLocal = d => { d = d || new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
const fechaHaceDias = n => { const d = new Date(); d.setDate(d.getDate()-n); return fechaLocal(d); };

// Lo que llega de la sincronización (Firestore) o de un respaldo importado se LIMPIA antes de usarlo:
// ids solo con letras/números/guiones, números donde van números y textos cortos (que además se pintan
// con escHtml). Las cuatro apps comparten el mismo dominio: un texto con código metido en un grupo
// podría leer las claves de IA y los datos de Fit F, Fit M y Facturas.
const _idOk = s => typeof s === 'string' && /^[a-z0-9-]{1,40}$/i.test(s);
const _modOk = s => _idOk(s) && !!MOD_POR_ID[s];   // y que el tema exista todavía (un grupo o mezcla guardados con un tema que se quitó ya no lo traen)
const _num0 = v => Math.max(0, Math.floor(Number(v)) || 0);
const _limpiarGrupos = gs => Array.isArray(gs) ? gs.filter(g => g && _idOk(g.id) && Array.isArray(g.mods))
  .map(g => ({ id:g.id, nombre:String(g.nombre == null ? '' : g.nombre).slice(0, 60), mods:g.mods.filter(_modOk) })) : [];
function _limpiarClase(c){
  if(!c || typeof c !== 'object' || !Array.isArray(c.mods)) return null;
  const o = { etiqueta:String(c.etiqueta == null ? '' : c.etiqueta).slice(0, 80), mods:c.mods.filter(_modOk) };
  if(_idOk(c.grupoId)) o.grupoId = c.grupoId;
  return o;
}
function _limpiarStats(s){
  const o = {};
  if(s && typeof s === 'object') Object.keys(s).forEach(id => { if(_idOk(id) && s[id] && typeof s[id] === 'object') o[id] = { ok:_num0(s[id].ok), fallo:_num0(s[id].fallo) }; });
  return o;
}
const _limpiarRacha = x => ({ actual:_num0(x && x.actual), mejor:_num0(x && x.mejor) });
const _nivelOk = n => ['facil','medio','dificil'].includes(n) ? n : 'medio';
// HTML de un respaldo importado (los errores guardados traen enunciados con dibujos): se le quitan
// scripts, iframes y atributos on… / javascript:, el resto (fracciones, SVG) se queda igual
function _limpiarHTML(s){
  if(typeof s !== 'string' || !/[<&]/.test(s)) return s;
  const doc = new DOMParser().parseFromString('<body>' + s + '</body>', 'text/html');
  doc.body.querySelectorAll('script,iframe,object,embed,link,meta,base,form,foreignObject').forEach(n => n.remove());
  doc.body.querySelectorAll('*').forEach(n => [...n.attributes].forEach(a => {
    if(/^on/i.test(a.name) || /^\s*(javascript|data):/i.test(a.value) && /href|src|action/i.test(a.name)) n.removeAttribute(a.name);
  }));
  return doc.body.innerHTML;
}
const _limpiarTodoHTML = v => typeof v === 'string' ? _limpiarHTML(v) : Array.isArray(v) ? v.map(_limpiarTodoHTML)
  : v && typeof v === 'object' ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, _limpiarTodoHTML(x)])) : v;

let nivel  = _nivelOk(leer('mate_nivel_v1', 'medio'));
// Modo "solo ayudante": el link …/Mate/?solo=ayud deja la app solo con Repaso de ayudante (sin las otras materias).
// Se guarda en mate_solo_v1 para que siga así aunque se abra sin el parámetro; ?solo=todas lo quita.
// OJO: el parámetro se queda en la dirección (no se limpia) porque el manifiesto del modo (ver más abajo) arranca con él.
const SOLO = (() => {
  try{
    const p = new URLSearchParams(location.search).get('solo');
    if(p === 'ayud') guardar('mate_solo_v1', 'ayud'); else if(p === 'todas') guardar('mate_solo_v1', null);
  }catch(e){}
  return leer('mate_solo_v1', null) === 'ayud' ? 'ayud' : null;
})();
let materia = SOLO || leer('mate_materia_v1', 'mate');   // qué materia se está estudiando ahora mismo
if(!Object.prototype.hasOwnProperty.call(MATERIAS, materia)) materia = 'mate';
let clase  = _limpiarClase(leer('mate_clase_v1', null));      // { etiqueta, mods:[] } — la mezcla activa ahora mismo
let grupos = _limpiarGrupos(leer('mate_grupos_v1', []));      // [{id, nombre, mods:[]}] — grupos guardados (ej. "Examen 1"),
                                                               // SÍ se sincronizan entre aparatos (ver _guardarGrupos)
const idGrupo = () => 'g'+Date.now().toString(36)+Math.random().toString(36).slice(2,5);
let stats  = _limpiarStats(leer('mate_stats_v1', {}));        // { modId:{ok, fallo} }
let racha  = _limpiarRacha(leer('mate_racha_v1', { actual:0, mejor:0 }));
let errores = leer('mate_errores_v1', []);          // [{modId, ej}], más reciente primero, tope 30
let historial = leer('mate_historial_v1', {});      // { "YYYY-MM-DD": cantidad de ejercicios }
let rachaDias = leer('mate_racha_dias_v1', { actual:0, mejor:0, ultimoDia:null });
let agruparTema = leer('mate_agrupar_v1', false);   // true = las repeticiones de un mismo tema salen juntas, no mezcladas
let repetirFallo = leer('mate_repetir_v1', false);  // true = una pregunta fallada vuelve a salir, igual, más adelante en la ronda
let unoPorTema = leer('mate_uno_v1', false);        // true = la mezcla trae 1 ejercicio de cada tema en vez de VECES_POR_TEMA (los bancos fijos del examen/ayudante no cambian); al tocarlo rehace lo que falta de la ronda en curso (_replanearRonda)
// [{fecha, correctas, total}], tope 30 — historial de resultados de "Modo examen" (ver
// finalizarExamen). El modo en sí no tiene botón que lo abra ahora mismo (ver CLAUDE.md,
// "Modo examen"); esto solo asegura que el resultado quede guardado el día que se reexponga.
let examenes = (Array.isArray(leer('mate_examenes_v1', [])) ? leer('mate_examenes_v1', []) : []).filter(e => e && typeof e === 'object')
  .map(e => ({ fecha:String(e.fecha || '').slice(0, 10), titulo:e.titulo ? String(e.titulo).slice(0, 60) : '', correctas:_num0(e.correctas), total:_num0(e.total) || 1 }));

function anotar(modId, ok){
  const s = stats[modId] || (stats[modId] = { ok:0, fallo:0 });
  ok ? s.ok++ : s.fallo++;
  guardar('mate_stats_v1', stats);
  racha.actual = ok ? racha.actual + 1 : 0;
  if(racha.actual > racha.mejor) racha.mejor = racha.actual;
  guardar('mate_racha_v1', racha);
  _empujarSync(modId, ok);
  _registrarHistorialYRachaDias();
}
function _registrarHistorialYRachaDias(){
  const hoy = fechaLocal();
  historial[hoy] = (historial[hoy]||0) + 1;
  guardar('mate_historial_v1', historial);
  if(rachaDias.ultimoDia !== hoy){
    const ayer = fechaHaceDias(1);
    rachaDias.actual = (rachaDias.ultimoDia === ayer) ? rachaDias.actual+1 : 1;
    rachaDias.mejor = Math.max(rachaDias.mejor, rachaDias.actual);
    rachaDias.ultimoDia = hoy;
    guardar('mate_racha_dias_v1', rachaDias);
  }
}
// la racha de días guardada no caduca sola (solo se actualiza al practicar) — esto es lo que
// hay que leer para MOSTRARLA, no rachaDias.actual directo, o "3 días seguidos" se queda
// pegado en pantalla una semana después de haber dejado de practicar
function _rachaDiasVigente(){
  if(rachaDias.actual <= 0 || !rachaDias.ultimoDia) return 0;
  const hoy = fechaLocal(), ayer = fechaHaceDias(1);
  return (rachaDias.ultimoDia === hoy || rachaDias.ultimoDia === ayer) ? rachaDias.actual : 0;
}
function _registrarError(ej){
  // si la MISMA pregunta (repetirFallo la reprograma igual, mismo enunciado) se acaba de
  // fallar dos veces seguidas dentro de la misma ronda, no la dupliques en la lista — es
  // el mismo error, no dos distintos
  if(errores[0] && errores[0].modId === ej.__mod && errores[0].ej.enunciado === ej.enunciado) return;
  errores.unshift({ modId: ej.__mod, ej });
  errores = errores.slice(0, 30);
  guardar('mate_errores_v1', errores);
}

/* ---------- sincronizar entre aparatos (Firebase, opcional) ---------- */
const FIREBASE_CONFIG = {
  apiKey: "AIzaSyDrOButk_G90Qcrj3BB-tEHa9l2lJrVc-0",
  authDomain: "mate-practica-matematicas.firebaseapp.com",
  projectId: "mate-practica-matematicas",
  storageBucket: "mate-practica-matematicas.firebasestorage.app",
  messagingSenderId: "511953502483",
  appId: "1:511953502483:web:8b0d98d48c1039d3f25ae6"
};
const URL_FB_APP = 'https://www.gstatic.com/firebasejs/10.14.1/firebase-app-compat.js';
const URL_FB_FS  = 'https://www.gstatic.com/firebasejs/10.14.1/firebase-firestore-compat.js';
const ALFABETO_CODIGO = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';  // sin 0/O/1/I/L, para no confundir al escribir

let syncCode = leer('mate_sync_code_v1', null);
if(typeof syncCode !== 'string' || !/^[A-Z0-9-]{4,30}$/.test(syncCode)) syncCode = null;
let syncDoc = null;      // referencia Firestore, null hasta conectar
let syncListo = false;   // true cuando ya hay listener activo
let _syncUnsub = null;

function generarCodigo(){
  let s = '';
  for(let g=0; g<3; g++){
    for(let i=0; i<4; i++) s += ALFABETO_CODIGO[Math.floor(Math.random()*ALFABETO_CODIGO.length)];
    if(g<2) s += '-';
  }
  return s;
}
async function _hashCodigo(codigo){
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(codigo.trim().toUpperCase()));
  return [...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,'0')).join('');
}
async function _initFirebase(){
  await cargarScript(URL_FB_APP);
  await cargarScript(URL_FB_FS);
  if(!firebase.apps.length){
    firebase.initializeApp(FIREBASE_CONFIG);
    try{ await firebase.firestore().enablePersistence({synchronizeTabs:true}); }catch(e){}  // offline: cachea y reintenta sola
  }
  return firebase.firestore();
}
function _fusionarStats(a, b){
  const ids = new Set([...Object.keys(a), ...Object.keys(b)]);
  const out = {};
  ids.forEach(id => {
    const x = a[id] || {ok:0, fallo:0}, y = b[id] || {ok:0, fallo:0};
    out[id] = { ok: (x.ok||0) + (y.ok||0), fallo: (x.fallo||0) + (y.fallo||0) };
  });
  return out;
}
// junta los grupos de los dos aparatos por id, sin perder ninguno — los id son al azar
// (idGrupo()) así que una colisión entre dos aparatos distintos es prácticamente imposible
function _unirGrupos(a, b){
  const vistos = new Set(a.map(g=>g.id));
  return a.concat(b.filter(g=>!vistos.has(g.id)));
}
async function conectarSync(codigo){           // se llama UNA vez, al vincular este aparato
  const db = await _initFirebase();
  const id = await _hashCodigo(codigo);
  const ref = db.collection('syncs').doc(id);
  const snap = await ref.get();
  const remoto = snap.exists ? snap.data() : {};
  grupos = _unirGrupos(_limpiarGrupos(remoto.grupos), grupos);
  guardar('mate_grupos_v1', grupos);
  await ref.set({
    stats: _fusionarStats(_limpiarStats(remoto.stats), stats),
    racha: { actual: (remoto.racha && remoto.racha.actual) || racha.actual,
             mejor: Math.max((remoto.racha && remoto.racha.mejor) || 0, racha.mejor) },
    nivel: remoto.nivel ? _nivelOk(remoto.nivel) : nivel,
    clase: remoto.clase !== undefined ? _limpiarClase(remoto.clase) : (clase || null),
    grupos
  }, { merge: true });
  syncDoc = ref;
  syncCode = codigo.trim().toUpperCase();
  guardar('mate_sync_code_v1', syncCode);
  _escucharSync();
}
async function _reengancharSync(){              // se llama en cada apertura, si ya había un código guardado
  if(!syncCode) return;
  const db = await _initFirebase();
  const id = await _hashCodigo(syncCode);
  syncDoc = db.collection('syncs').doc(id);
  _escucharSync();
}
function _escucharSync(){
  if(!syncDoc || syncListo) return;
  syncListo = true;
  _syncUnsub = syncDoc.onSnapshot(snap => {
    const d = snap.data();
    if(!d) return;
    // Firestore solo guarda el campo que se incrementó (ok o fallo) — un tema sin fallos
    // nunca queda con esa clave. Se normaliza al recibir para que pct() no dé NaN.
    if(d.stats) stats = _limpiarStats(d.stats);
    if(d.racha){ const rr = _limpiarRacha(d.racha); racha.actual = rr.actual; racha.mejor = Math.max(racha.mejor||0, rr.mejor); }
    if(d.nivel) nivel = _nivelOk(d.nivel);
    if(d.clase !== undefined) clase = _limpiarClase(d.clase);
    if(d.grupos !== undefined) grupos = _limpiarGrupos(d.grupos);
    guardar('mate_stats_v1', stats); guardar('mate_racha_v1', racha);
    guardar('mate_nivel_v1', nivel); guardar('mate_clase_v1', clase);
    guardar('mate_grupos_v1', grupos);
    // si estás mirando Inicio o Progreso cuando llega el cambio del otro aparato, refresca sola
    if(_pantallaActual === pantallaInicio || _pantallaActual === pantallaStats) _pantallaActual();
  }, err => console.warn('sync:', err.message));
}
// las escrituras se juntan unos segundos en vez de mandar una por cada respuesta — menos
// veces que se despierta la radio del teléfono para lo mismo
let _syncPendiente = null, _syncTimer = null;
function _empujarSync(modId, ok){
  if(!syncDoc) return;
  if(!_syncPendiente) _syncPendiente = { stats:{} };
  const p = _syncPendiente.stats[modId] || (_syncPendiente.stats[modId] = { ok:0, fallo:0 });
  p[ok ? 'ok' : 'fallo']++;
  _syncPendiente.racha = { actual: racha.actual, mejor: racha.mejor };
  clearTimeout(_syncTimer);
  _syncTimer = setTimeout(_flushSync, 4000);
}
function _flushSync(){
  clearTimeout(_syncTimer); _syncTimer = null;
  if(!syncDoc || !_syncPendiente) return;
  const p = _syncPendiente; _syncPendiente = null;
  const statsInc = {};
  Object.keys(p.stats).forEach(id => {
    statsInc[id] = {};
    if(p.stats[id].ok)    statsInc[id].ok    = firebase.firestore.FieldValue.increment(p.stats[id].ok);
    if(p.stats[id].fallo) statsInc[id].fallo = firebase.firestore.FieldValue.increment(p.stats[id].fallo);
  });
  syncDoc.set({ stats: statsInc, racha: p.racha }, { merge: true }).catch(()=>{});
}
function desconectarSync(){
  _flushSync();
  if(_syncUnsub) _syncUnsub();
  _syncUnsub = null; syncDoc = null; syncListo = false; syncCode = null;
  localStorage.removeItem('mate_sync_code_v1');
}
// suelta la conexión en vivo con Firestore cuando la app pasa a segundo plano (batería), y la
// vuelve a enganchar al regresar — antes se quedaba escuchando para siempre en background
document.addEventListener('visibilitychange', () => {
  if(!syncCode) return;
  if(document.visibilityState === 'hidden'){
    _flushSync();
    if(_syncUnsub){ _syncUnsub(); _syncUnsub = null; syncListo = false; }
  } else if(document.visibilityState === 'visible' && syncDoc && !syncListo){
    _escucharSync();
  }
});
// "Automático (por hora)" solo se reevaluaba al arrancar o al cambiar la preferencia — si la
// app se queda abierta cruzando las 7 pm/6 am, se quedaba en el tema de antes hasta reabrirla.
// aplicarTema() es barata (lee un color de localStorage y alterna una clase) y no hace nada
// en los otros 3 modos (el color no cambió), así que no hace falta filtrar por getTemaModo().
document.addEventListener('visibilitychange', () => {
  if(document.visibilityState === 'visible') aplicarTema();
});
// reintenta la sincronización sola al recuperar internet — antes se quedaba desconectada
// hasta la próxima vez que se abriera la app
window.addEventListener('online', () => {
  if(!syncCode) return;
  if(!syncDoc) _reengancharSync().catch(()=>{});
  else if(!syncListo) _escucharSync();
});
const pct = s => { const t = s.ok + s.fallo; return t ? Math.round(s.ok*100/t) : null; };

/* módulos disponibles ahora mismo (según el modo clase) */
function modulosActivos(){
  // clase.mods es de UNA materia — si cambiaste de materia y quedó un grupo/mezcla de la otra
  // sin quitar, se ignora en vez de mezclar módulos de las dos materias en una misma ronda
  if(clase && clase.mods && clase.mods.length){
    const ms = clase.mods.map(id => MOD_POR_ID[id]).filter(m => m && m.clase === materia);
    if(ms.length) return ms;
  }
  return MODULOS.filter(m => m.clase === materia && !m.extra);   // "Extra" (Repaso de ayudante) no entra en la mezcla general
}
/* sortea uno de "ms" dando más peso a los que van peor — la usa iniciarExamen() (el examen al azar) */
function elegirDe(ms){
  const pesos = ms.map(m => {
    const s = stats[m.id] || { ok:0, fallo:0 };
    return 1 + s.fallo / (s.ok + s.fallo + 1);
  });
  let r = Math.random() * pesos.reduce((a,b)=>a+b, 0);
  for(let i=0; i<ms.length; i++){ r -= pesos[i]; if(r <= 0) return ms[i]; }
  return ms[ms.length-1];
}

