// agenda la pregunta fallada para que vuelva a salir, igual (mismo enunciado y números), más
// adelante en la misma ronda — nunca la próxima (esperar arranca en 2 como mínimo), y la ronda
// se alarga un puesto para que le entre. Sirve tanto para mezcla (sesionCola) como para tema fijo.
function _programarRepeticion(){
  sesionPendientes.push({ modId: ejActual.__mod, ej: Object.assign({}, ejActual), esperar: R(2,4) });
  sesionTotal++;
}
let ultimoFeedback = null;// resultado de verificar() del último responder(), para poder retomarlo
let ultimoProceso = '';   // lo que el usuario escribió en "Tu proceso" antes de responder (un paso por línea)
let _reintento = false;    // true = el ejercicio se reinició después de contestarlo o de ver la explicación (ya no cuenta otra vez)
let ultimaEntrada = null; // lo que respondió (ent de responder()), para que la IA pueda revisarlo después
// "Tu proceso": una caja por paso, opcional, en todos los ejercicios. Va FUERA de #zonaEntrada
// para que la calculadora no escriba ahí y no se ponga opaca al contestar.
const attrEsc = s => escHtml(s).replace(/"/g, '&quot;');
// cada paso es una fila de pedazos: cajas de texto y, si hace falta, fracciones con arriba y abajo (botón a/b).
// Se guardan como una línea de texto; la fracción va como ⟦arriba|abajo⟧ para poder volver a dibujarla.
const _ptHTML = (v, id, ph) => `<input class="campo pt"${id ? ` id="${id}"` : ''} autocomplete="off" autocapitalize="off"${ph ? ` placeholder="${ph}"` : ''} value="${attrEsc(v)}">`;
const _frHTML = (n, d, x = true) => `<span class="pfr">${x ? `<button type="button" class="pfrX" onclick="quitarFraccion(this)" aria-label="Quitar la fracción">×</button>` : ''}<input class="campo pn" autocomplete="off" autocapitalize="off" placeholder="arriba" value="${attrEsc(n)}"><i class="pbarra"></i><input class="campo pd" autocomplete="off" autocapitalize="off" placeholder="abajo" value="${attrEsc(d)}"></span>`;
// igualdad de fracciones a/b = c/d (botón de cada paso)
const _faHTML = (a, b, c, d, k) => `<span class="pfa"><button type="button" class="pfrX" onclick="quitarFraccion(this)" aria-label="Quitar la fracción con flechas">×</button>
  <span class="pfaFila">${_frHTML(a, b, false)}<b>=</b>${_frHTML(c, d, false)}</span></span>`;
const _RX_PARTE = /⟦([^|⟧]*)\|([^⟧]*)⟧|⟪([^|⟫]*)\|([^|⟫]*)\|([^|⟫]*)\|([^|⟫]*)\|([^⟫]*)⟫/g;
function pasoFilaHTML(i, v){
  v = String(v || ''); let h = '', ult = 0, m;
  _RX_PARTE.lastIndex = 0;
  while((m = _RX_PARTE.exec(v))){
    h += (ult === 0 && !h) ? _ptHTML(v.slice(0, m.index), 'inP' + i, `Paso ${i+1}`) : _ptHTML(v.slice(ult, m.index), '', '');
    h += m[1] !== undefined ? _frHTML(m[1], m[2]) : _faHTML(m[3], m[4], m[5], m[6], m[7]);
    ult = m.index + m[0].length;
  }
  h += h ? _ptHTML(v.slice(ult), '', '') : _ptHTML(v, 'inP' + i, `Paso ${i+1}`);
  return `<div class="pasoFila"><span>${i+1}</span><div class="pasoPartes">${h}</div><button type="button" class="pasoFrBtn" onclick="agregarFraccion(this, true)" aria-label="Agregar dos fracciones iguales (a/b = c/d)" title="Dos fracciones con = en medio">a/b=c/d</button></div>`;
}
function agregarFraccion(btn, flechas){
  const partes = btn.closest('.pasoFila').querySelector('.pasoPartes');
  partes.insertAdjacentHTML('beforeend', (flechas ? _faHTML('', '', '', '', '') : _frHTML('', '')) + _ptHTML('', '', ''));
  partes.lastElementChild.previousElementSibling.querySelector('.pn').focus();
}
function quitarFraccion(x){ const fr = x.closest('.pfa, .pfr'), sig = fr.nextElementSibling, prev = fr.previousElementSibling;
  if(sig && prev && sig.classList.contains('pt') && prev.classList.contains('pt')){ prev.value = (prev.value + ' ' + sig.value).trim(); sig.remove(); }
  const foco = prev || fr.parentNode.firstElementChild; fr.remove(); if(foco && foco.focus) foco.focus(); }
function procesoHTML(){
  const texto = (_borradorPend && _borradorPend.proceso) || ((respondido || vioExpl) && ultimoProceso) || '';
  const guardados = texto ? texto.split('\n') : [];
  const n = Math.max(3, guardados.length);
  const abierto = !!texto;   // oculto por defecto; se ve solo si ya hay algo escrito (borrador o proceso de un intento anterior)
  return `<div class="procesoCaja"><div class="procesoTit"><span>Tu proceso</span>
      <button type="button" id="btnOcultarProceso" class="procesoOcultar" onclick="toggleProceso()">${abierto ? '▲ Ocultar' : '▼ Mostrar'}</button></div>
    <div id="cuerpoProceso"${abierto ? '' : ' style="display:none"'}><div id="listaPasos">${Array.from({length:n}, (_, i) => pasoFilaHTML(i, guardados[i] || '')).join('')}</div>
    <button type="button" class="btn sec chico" onclick="agregarPaso()">+ Agregar paso</button></div></div>`;
}
// esconde / muestra solo la caja de "Tu proceso" (lo que escribiste se queda guardado)
function toggleProceso(){
  const c = $('cuerpoProceso'), b = $('btnOcultarProceso'); if(!c || !b) return;
  const ocultar = c.style.display !== 'none'; c.style.display = ocultar ? 'none' : ''; b.textContent = ocultar ? '▼ Mostrar' : '▲ Ocultar';
}
function agregarPaso(){ const l = $('listaPasos'), i = l.children.length; l.insertAdjacentHTML('beforeend', pasoFilaHTML(i, '')); $('inP' + i).focus(); }
const leerProceso = () => [...document.querySelectorAll('#listaPasos .pasoPartes')].map(fila => [...fila.children].map(x => {
    if(x.classList.contains('pt')) return x.value.trim();
    if(x.classList.contains('pfr')){ const n = x.querySelector('.pn').value.trim(), d = x.querySelector('.pd').value.trim(); return (n || d) ? `⟦${n}|${d}⟧` : ''; }
    if(x.classList.contains('pfa')){ const v = [...x.querySelectorAll('.pn, .pd')].map(i => i.value.trim().replace(/[|⟫]/g, ''));   // n1, d1, n2, d2 en orden de la pantalla
      return v.some(Boolean) ? `⟪${v.join('|')}|⟫` : ''; }
    return ''; }).filter(Boolean).join(' ')).filter(Boolean).join('\n');

/* ---------- retomar donde quedó (mate_sesion_v1) ---------- */
// lo escrito y todavía sin comprobar (Tu proceso y las casillas de respuesta), si en pantalla está ESTE ejercicio
function _borradorActual(){
  const z = $('zonaEntrada');
  if(respondido || !z || main.dataset.ej !== String(sesionIdx)) return null;
  const entrada = {};
  z.querySelectorAll('input[id], select[id]').forEach(x => { if(x.value !== '') entrada[x.id] = x.value; });
  const proceso = leerProceso();
  return (proceso || Object.keys(entrada).length) ? { proceso, entrada } : null;
}
// ¿esta página de la ronda está (o se guarda) en su propia clave? Las de las prácticas del examen no: se vuelven a armar iguales (las repeticiones sí)
const _paginaGuardable = i => { const ej = sesionEjs[i], m = ej && MOD_POR_ID[ej.__mod]; return !!ej && !(m && m.nuevaRonda && !ej.__rep); };
// Un fallo o una repetición pendiente es el MISMO ejercicio de una página ya guardada: no se copia otra vez (cada copia pesa hasta 43 KB y se reescribía en cada respuesta), solo su número de página (p)
function _compactarEj(item){
  if(!item || !item.ej) return item;
  const i = sesionEjs.findIndex((e, k) => e && _paginaGuardable(k) && e.__mod === item.ej.__mod && e.enunciado === item.ej.enunciado);
  if(i < 0) return item;
  const { ej, ...resto } = item; return { ...resto, p:i };
}
const _desCompactarEj = lista => (Array.isArray(lista) ? lista : []).map(it => {
  if(!it || it.p == null || it.ej) return it;
  const ej = sesionEjs[it.p]; if(!ej) return null;
  const { p, ...resto } = it; return { ...resto, ej };
}).filter(Boolean);
function guardarSesion(){
  clearTimeout(_borradorT); _borradorT = null;
  // cada página de la ronda se guarda UNA sola vez, en su propia clave (antes se reescribía la ronda entera, hasta 365 KB, en cada respuesta); primero ellas, para que lo compacto de abajo apunte a algo que ya existe
  _ejsSucios.forEach(i => { if(_paginaGuardable(i)) guardar('mate_sesion_ej_' + i, sesionEjs[i]); });
  _ejsSucios.clear();
  guardar('mate_sesion_v1', { modId: modActual.id, esTemaFijo, capFijo, sesionHechos, sesionCorrectos,
    sesionCola, sesionPendientes: sesionPendientes.map(_compactarEj), sesionFallos: sesionFallos.map(_compactarEj), temasEjemploVisto, sesionTotal, sesionIdx, sesionAbiertos, sesionVistos, sesionRes, sesionOrden, ejActual, respondido, vioExpl, ordenSel, ultimoFeedback, ultimoProceso, ultimaEntrada, borrador: _borradorActual() });
}
const _borrarPaginasSesion = () => { try{ Object.keys(localStorage).filter(k => k.startsWith('mate_sesion_ej_') || k === 'mate_sesion_ejs_v1').forEach(k => localStorage.removeItem(k)); }catch(e){} };
const borrarSesion = () => { try{ localStorage.removeItem('mate_sesion_v1'); }catch(e){} _borrarPaginasSesion(); _ejsSucios.clear(); };
// lo que se escribe se guarda solo, un momento después de dejar de escribir, y al salir de la app:
// si Android cierra la app mientras miras otra cosa, al volver está todo donde lo dejaste
let _borradorT = null;
const _alEscribir = e => {
  if(!e.target.closest || !e.target.closest('#zonaProceso, #zonaEntrada') || !modActual || examen || modoErrores || modoRepasoRonda || main.dataset.ej === undefined) return;
  clearTimeout(_borradorT); _borradorT = setTimeout(guardarSesion, 700);
};
document.addEventListener('input', _alEscribir);
document.addEventListener('change', _alEscribir);
document.addEventListener('visibilitychange', () => { if(document.visibilityState === 'hidden' && _borradorT) guardarSesion(); });
function restaurarSesion(){
  const s = leer('mate_sesion_v1', null);
  if(!s || !MOD_POR_ID[s.modId] || !s.ejActual) return false;
  // una ronda guardada que trae un tema que ya no existe (se quitó) se descarta entera: seguirla se atoraría al llegar a su turno
  const ids = [...(s.sesionOrden || []), ...(s.sesionCola || []), ...(s.sesionPendientes || []).map(p => p && p.modId), ...(s.sesionFallos || []).map(p => p && p.modId)];
  if(!ids.every(id => id == null || id === '*' || MOD_POR_ID[id])){ borrarSesion(); return false; }
  modActual = MOD_POR_ID[s.modId];
  esTemaFijo = s.esTemaFijo; capFijo = s.capFijo; sesionHechos = s.sesionHechos || 1;
  sesionCorrectos = s.sesionCorrectos || 0; sesionCola = s.sesionCola || [];
  temasEjemploVisto = s.temasEjemploVisto || {};
  sesionTotal = s.sesionTotal || sesionCola.length || SESION_TEMA;
  ejActual = s.ejActual; respondido = s.respondido; vioExpl = s.vioExpl;
  sesionIdx = s.sesionIdx != null ? s.sesionIdx : sesionHechos - 1;
  sesionAbiertos = s.sesionAbiertos || Object.fromEntries(Array.from({length:sesionHechos}, (_, i) => [i, true]));
  sesionVistos = s.sesionVistos || {}; sesionRes = s.sesionRes || {}; sesionOrden = s.sesionOrden || [];
  sesionEjs = []; _ejsSucios = new Set();
  const viejas = leer('mate_sesion_ejs_v1', null);   // formato anterior: toda la ronda en una sola clave → se pasa a una clave por página
  Object.keys(sesionAbiertos).forEach(k => { const i = +k, ej = (Array.isArray(viejas) && viejas[i]) || leer('mate_sesion_ej_' + i, null); if(ej) sesionEjs[i] = ej; });
  if(Array.isArray(viejas)){ try{ localStorage.removeItem('mate_sesion_ejs_v1'); }catch(e){} sesionEjs.forEach((e, i) => { if(e) _ejsSucios.add(i); }); }
  sesionEjs[sesionIdx] = ejActual;
  sesionPendientes = _desCompactarEj(s.sesionPendientes); sesionFallos = _desCompactarEj(s.sesionFallos);   // los que solo guardaron su número de página (p) recuperan su ejercicio
  _borradorPend = !respondido && s.borrador ? s.borrador : null;
  ordenSel = s.ordenSel || []; ultimoFeedback = s.ultimoFeedback || null;
  if(modActual.nuevaRonda && ejActual && ejActual.__n != null){   // las 30 del examen: sigue desde donde ibas
    // la explicación guardada puede ser de una versión vieja de la app: se vuelve a sacar la de ahora (la pregunta es la misma)
    modActual._sig = ejActual.__n; const fresco = modActual.gen(nivel);
    ejActual.explicacion = fresco.explicacion; ejActual.enunciado = fresco.enunciado;
  }
  ultimoProceso = s.ultimoProceso || '';
  ultimaEntrada = s.ultimaEntrada === undefined ? null : s.ultimaEntrada;
  pintarEjercicio();
  if(_borradorPend){   // las casillas de respuesta que estaban escritas
    Object.entries(_borradorPend.entrada || {}).forEach(([id, v]) => { const x = $(id); if(x && $('zonaEntrada').contains(x)) x.value = v; });
    _borradorPend = null;
  }
  if(respondido && ultimoFeedback) mostrarFb(ultimoFeedback, false);   // ya contestó de verdad
  else if(vioExpl) _pintarVistaExplicacion();                          // solo vio la explicación, sigue pudiendo responder
  return true;
}

// barra flotante de abajo — cada pantalla llama esto con su pestaña (o con null para
// ocultarla durante una ronda/examen, donde un toque de más te sacaría a media pregunta)
const bn = $('bn');
// lente Liquid Glass que se desliza sobre la pestaña activa — igual que positionBnLens() de Fit-F
let _bnLenteLista = false;
function _posicionarLente(){
  const lente = $('bnLens');
  const activo = bn.querySelector('.bn-item.active');
  if(!lente || !activo){ if(lente) lente.style.opacity = '0'; return; }
  if(!_bnLenteLista) lente.style.transition = 'none';   // el primer posicionamiento no se anima
  lente.style.opacity = '1';
  lente.style.left = activo.offsetLeft + 'px';
  lente.style.top = activo.offsetTop + 'px';
  lente.style.width = activo.offsetWidth + 'px';
  lente.style.height = activo.offsetHeight + 'px';
  if(!_bnLenteLista){ void lente.offsetWidth; lente.style.transition = ''; _bnLenteLista = true; }
}
window.onresize = () => { _bnLenteLista = false; _posicionarLente(); };
function _barra(activa){
  delete main.dataset.ej;   // pintarEjercicio la vuelve a poner: así el borrador nunca se toma de otra pantalla
  bn.classList.toggle('oculta', !activa);
  bn.querySelectorAll('.bn-item').forEach(b => b.classList.toggle('active', b.dataset.tab === activa));
  if(activa) _posicionarLente();
}

// tarjeta flotante de "Grupos de examen" desde Inicio — sin salir de la pantalla para
// elegir cuál practicar; "Ver todos los grupos" sigue llevando a la pantalla de editar/crear
function menuGrupos(e){
  e.stopPropagation();
  if($('menuGrupos')){ cerrarMenuGrupos(); return; }
  const btn = e.currentTarget;
  const r = btn.getBoundingClientRect();
  const menu = document.createElement('div');
  menu.id = 'menuGrupos';
  menu.className = 'card menuFlot';
  const gs = gruposMateria();
  menu.innerHTML = gs.length ? gs.map(g => `
      <button class="ajRow" onclick="cerrarMenuGrupos();practicarGrupo('${g.id}')">
        <div style="flex:1"><div class="ajTitulo">${escHtml(g.nombre)}</div>
          <div class="ajSub">${nTemas(g.mods.length)} · ${tamanoMezcla(g.mods)} preguntas</div></div>
        <span class="ajCheck" style="opacity:${clase && clase.grupoId===g.id ? 1 : 0}">✓</span>
      </button>`).join('') +
      `<button class="ajRow" onclick="cerrarMenuGrupos();ir('grupos')"><div class="ajTitulo">Ver todos los grupos</div></button>`
    : `<div style="padding:10px">
        <div class="nota" style="margin:0 0 10px">Todavía no tienes ningún grupo.</div>
        <button class="btn amar chico" style="margin:0" onclick="cerrarMenuGrupos();ir('grupos')">+ Crear grupo nuevo</button>
      </div>`;
  menu._btn = btn;   // el propio botón cuenta como "adentro" — si no, un 2do toque lo cierra
                      // y lo vuelve a abrir en el mismo clic (el listener de afuera es capture,
                      // corre antes que el onclick del botón)
  document.body.appendChild(menu);
  const ancho = Math.min(300, window.innerWidth - 16);
  menu.style.width = ancho + 'px';
  menu.style.left = Math.max(8, Math.min(r.left, window.innerWidth - ancho - 8)) + 'px';
  menu.style.top = (r.bottom + 6) + 'px';
  setTimeout(() => document.addEventListener('click', _cerrarMenuGruposFuera, true), 0);
}
function cerrarMenuGrupos(){
  const m = $('menuGrupos'); if(m) m.remove();
  document.removeEventListener('click', _cerrarMenuGruposFuera, true);
}
function _cerrarMenuGruposFuera(e){
  const m = $('menuGrupos');
  if(m && (m.contains(e.target) || e.target === m._btn || (m._btn && m._btn.contains(e.target)))) return;
  cerrarMenuGrupos();
}

// calculadora — botón flotante, disponible en toda la app (incluso practicando) para
// comprobar una cuenta a mano; no toca ninguna variable de la práctica.
// calcExpr guarda la expresión tal como se escribe (números, signos y paréntesis) y calcVal el
// número que se está escribiendo ahora mismo — nada se calcula hasta "=", y "=" respeta el
// orden de operaciones (× y ÷ antes que + y −, paréntesis primero), como en el examen.
let calcVal = '', calcExpr = [], calcNuevo = false, calcRes = null;   // calcRes = último resultado {v, f:{n,d}|null}
// cuentas ya resueltas (con "=") en el ejercicio actual — se reinicia con cada ejercicio nuevo
// (ver los sitios que hacen "calcHist = []"), no al abrir/cerrar la calculadora, así que
// si la cierras y la vuelves a abrir en el MISMO ejercicio sigues viendo lo que ya hiciste.
let calcHist = [];   // [{expr, res}]
const _CALC_OPS = ['+', '-', '×', '÷'];
const _calcEsOp = t => _CALC_OPS.includes(t);
const _calcEsNum = t => t !== undefined && !_calcEsOp(t) && t !== '(' && t !== ')';
const _calcMostrar = t => t === '-' ? '−' : t.replace(/^-(?=[\d.])/, '−');
function _calcRenderHist(){
  const el = $('calcHist'); if(!el) return;
  el.style.display = calcHist.length ? 'block' : 'none';
  el.innerHTML = calcHist.slice().reverse().map((h, k) =>
    `<button class="calcHistFila" onclick="_calcUsarHist(${calcHist.length - 1 - k})">
      <span>${escHtml(h.expr)} =</span><b>${escHtml(h.res)}</b>
    </button>`).join('');
}
function _calcUsarHist(k){ const h = calcHist[k]; if(!h) return; if(calcNuevo){ calcExpr = []; calcNuevo = false; } calcVal = String(h.v); _calcRender(); }
function _calcRender(){
  const partes = calcExpr.map(_calcMostrar).concat(calcVal ? [calcVal.replace(/^-/, '−')] : []);
  $('calcPantalla').textContent = partes.length ? partes.join(' ') : '0';
  const fr = $('calcFrac');
  if(fr){ const f = calcNuevo && calcRes && calcRes.f; fr.textContent = f ? '= ' + _calcFracTxt(f) : ''; fr.style.display = f ? '' : 'none'; }
}
// 0.375 → 3/8 ; 1.75 → 7/4 (1 3/4). Solo si el decimal es de verdad una fracción con denominador chico.
function _calcAFraccion(x){
  if(!isFinite(x) || Number.isInteger(x)) return null;
  for(let d = 2; d <= 1000; d++){ const n = Math.round(x * d); if(Math.abs(n / d - x) < 1e-9) return { n, d }; }
  return null;
}
const _calcFracTxt = f => { const a = Math.abs(f.n), s = f.n < 0 ? '−' : '';
  return s + a + '/' + f.d + (a > f.d ? ` (${s}${Math.floor(a / f.d)} ${a % f.d}/${f.d})` : ''); };
function abrirCalc(){
  calcVal = ''; calcExpr = []; calcNuevo = false; calcRes = null;
  _calcRender();
  _calcRenderHist();
  // "Usar" aparece si hay al menos un campo de respuesta donde ponerlo (num, frac, mixto,
  // ángulos con figura...); los pasos de "Tu proceso" están en #zonaProceso, fuera de #zonaEntrada,
  // así que este selector no los toma. Fuera de un ejercicio no hay #zonaEntrada: no sale.
  const z = $('zonaEntrada');
  $('calcUsarBtn').style.display = z && z.querySelector('input.campo') ? '' : 'none';
  $('calcOv').style.display = 'flex';
}
function cerrarCalc(){ $('calcOv').style.display = 'none'; }
// Llena el primer campo VACÍO (arriba antes que abajo, entero antes que la fracción...,
// según el orden en que aparecen en pantalla); si ya están todos llenos, empieza de nuevo
// por el primero. Si el resultado es una fracción y el ejercicio pide fracción o número
// mixto, la pone completa (arriba, abajo y el entero).
function calcUsar(){
  const z = $('zonaEntrada'); if(!z) return;
  const v = calcNuevo && calcRes ? calcRes : (calcVal && calcVal !== '-' ? { v: parseFloat(calcVal), f: _calcAFraccion(parseFloat(calcVal)) } : null);
  if(!v || !isFinite(v.v)) return;
  const f = v.f, inN = z.querySelector('#inN'), inD = z.querySelector('#inD'), inE = z.querySelector('#inE');
  if(f && inN && inD){
    if(inE){ const a = Math.abs(f.n); inE.value = (f.n < 0 ? '-' : '') + Math.floor(a / f.d); inN.value = a % f.d; }
    else inN.value = f.n;
    inD.value = f.d;
    return cerrarCalc();
  }
  const campos = [...z.querySelectorAll('input.campo')];
  if(!campos.length) return;
  (campos.find(c => c.value === '') || campos[0]).value = _calcFormato(v.v);
  cerrarCalc();
}
function _calcEmpezarSiResultado(usarlo){
  if(!calcNuevo) return;
  calcNuevo = false;
  calcExpr = []; calcVal = usarlo && calcRes && isFinite(calcRes.v) ? _calcFormato(calcRes.v) : '';
}
function calcDigito(d){
  _calcEmpezarSiResultado(false);
  if(calcExpr[calcExpr.length - 1] === ')' && !calcVal) calcExpr.push('×');
  if(calcVal === '0') calcVal = d;
  else if(calcVal === '-0') calcVal = '-' + d;
  else if(calcVal.replace(/[-.]/g, '').length < 12) calcVal += d;
  _calcRender();
}
function calcPunto(){
  _calcEmpezarSiResultado(false);
  if(calcExpr[calcExpr.length - 1] === ')' && !calcVal) calcExpr.push('×');
  if(!calcVal || calcVal === '-') calcVal += '0.';
  else if(calcVal.indexOf('.') === -1) calcVal += '.';
  _calcRender();
}
function calcSigno(){
  _calcEmpezarSiResultado(true);
  calcVal = calcVal.startsWith('-') ? calcVal.slice(1) : '-' + calcVal;
  _calcRender();
}
function calcPorcentaje(){
  _calcEmpezarSiResultado(true);
  if(!calcVal || calcVal === '-') return;
  // "200 + 15 %" es 15 % DE 200 (= 30, total 230), como en la calculadora del teléfono; después de × o ÷ (o sin nada antes) el % es solo ÷ 100 (80 × 15 % = 80 × 0.15)
  const ult = calcExpr[calcExpr.length - 1], antes = calcExpr.slice(0, -1);
  if((ult === '+' || ult === '-') && antes.length && antes.filter(t => t === '(').length === antes.filter(t => t === ')').length){
    const base = _calcEvaluar(antes);
    if(isFinite(base)){ calcVal = _calcFormato(base * parseFloat(calcVal) / 100); _calcRender(); return; }
  }
  calcVal = _calcFormato(parseFloat(calcVal) / 100);
  _calcRender();
}
function calcClear(){
  calcVal = ''; calcExpr = []; calcNuevo = false; calcRes = null;
  _calcRender();
}
function calcBorrar(){
  if(calcNuevo){ calcClear(); return; }
  if(calcVal){ calcVal = calcVal.slice(0, -1); if(calcVal === '-') calcVal = ''; }
  else if(calcExpr.length){ const t = calcExpr.pop(); if(_calcEsNum(t)) calcVal = t.slice(0, -1) === '-' ? '' : t.slice(0, -1); }
  _calcRender();
}
function calcOp(op){
  _calcEmpezarSiResultado(true);
  if(calcVal === '-') return;
  if(calcVal){ calcExpr.push(calcVal); calcVal = ''; }
  const ult = calcExpr[calcExpr.length - 1];
  if(ult === undefined || ult === '('){ if(op === '-'){ calcVal = '-'; _calcRender(); } return; }   // un "−" al empezar es el signo del número
  if(_calcEsOp(ult)) calcExpr[calcExpr.length - 1] = op;   // cambiar de opinión sobre el signo: se reemplaza
  else calcExpr.push(op);
  _calcRender();
}
function calcParen(p){
  _calcEmpezarSiResultado(p === ')');
  if(p === '('){
    if(calcVal === '-'){ calcVal = ''; calcExpr.push('-1', '×'); }
    else if(calcVal){ calcExpr.push(calcVal, '×'); calcVal = ''; }
    else if(calcExpr.length && (_calcEsNum(calcExpr[calcExpr.length - 1]) || calcExpr[calcExpr.length - 1] === ')')) calcExpr.push('×');
    calcExpr.push('(');
  } else {
    const abiertos = calcExpr.filter(t => t === '(').length - calcExpr.filter(t => t === ')').length;
    if(abiertos <= 0) return;
    if(calcVal && calcVal !== '-'){ calcExpr.push(calcVal); calcVal = ''; }
    const ult = calcExpr[calcExpr.length - 1];
    if(_calcEsOp(ult) || ult === '(') return;
    calcExpr.push(')');
  }
  _calcRender();
}
// evalúa con el orden de operaciones: primero lo de los paréntesis, luego × y ÷, al final + y −
function _calcEvaluar(ts){
  let i = 0;
  const num = () => {
    const t = ts[i];
    if(t === '('){ i++; const v = suma(); if(ts[i] === ')') i++; return v; }
    if(t === '-'){ i++; return -num(); }
    i++; return parseFloat(t);
  };
  const prod = () => { let v = num(); while(ts[i] === '×' || ts[i] === '÷'){ const o = ts[i++], b = num(); v = o === '×' ? v * b : (b === 0 ? NaN : v / b); } return v; };
  const suma = () => { let v = prod(); while(ts[i] === '+' || ts[i] === '-'){ const o = ts[i++], b = prod(); v = o === '+' ? v + b : v - b; } return v; };
  const v = suma();
  return i === ts.length ? v : NaN;
}
function _calcFormato(n){
  if(!isFinite(n)) return 'Error';
  return String(Math.round(n * 1e8) / 1e8);   // recorta el ruido de coma flotante
}
function calcIgual(){
  if(calcNuevo) return;
  const ts = calcExpr.slice(); if(calcVal && calcVal !== '-') ts.push(calcVal);
  while(ts.length && (_calcEsOp(ts[ts.length - 1]) || ts[ts.length - 1] === '(')) ts.pop();   // un signo o "(" suelto al final no cuenta
  if(!ts.length) return;
  const faltan = ts.filter(t => t === '(').length - ts.filter(t => t === ')').length;
  for(let k = 0; k < faltan; k++) ts.push(')');   // los paréntesis sin cerrar se cierran solos
  const v = _calcEvaluar(ts), res = _calcFormato(v);
  calcRes = { v, f: _calcAFraccion(Math.round(v * 1e9) / 1e9) };
  calcHist.push({ expr: ts.map(_calcMostrar).join(' '), res: calcRes.f ? `${res} = ${_calcFracTxt(calcRes.f)}` : res, v });
  calcExpr = res === 'Error' ? [] : [res]; calcVal = ''; calcNuevo = true;
  $('calcPantalla').textContent = res.replace(/^-/, '−');
  const fr = $('calcFrac'); if(fr){ fr.textContent = calcRes.f ? '= ' + _calcFracTxt(calcRes.f) : ''; fr.style.display = calcRes.f ? '' : 'none'; }
  _calcRenderHist();
}
// teclado físico para la calculadora — solo actúa mientras el overlay está abierto, así que no
// interfiere con Enter en los inputs de la práctica ni con ningún otro atajo de la página.
document.addEventListener('keydown', e => {
  if($('calcOv').style.display !== 'flex') return;
  if(/^[0-9]$/.test(e.key)) calcDigito(e.key);
  else if(e.key === '.' || e.key === ',') calcPunto();
  else if(e.key === '+') calcOp('+');
  else if(e.key === '-') calcOp('-');
  else if(e.key === '*' || e.key === 'x') calcOp('×');
  else if(e.key === '/'){ e.preventDefault(); calcOp('÷'); }   // '/' abre la búsqueda rápida en Firefox
  else if(e.key === '(' || e.key === ')') calcParen(e.key);
  else if(e.key === '%') calcPorcentaje();
  else if(e.key === 'Enter' || e.key === '=') calcIgual();
  else if(e.key === 'u' || e.key === 'U') calcUsar();
  else if(e.key === 'Escape') cerrarCalc();
  else if(e.key === 'Backspace') calcBorrar();
  else if(e.key === 'Delete') calcClear();
  else return;
  e.preventDefault();
});
// Enter para "Siguiente ejercicio" una vez que ya se contestó — se busca el botón en vez de
// mirar la variable `respondido` (que queda pegada en true al navegar a otra pantalla) para
// no disparar esto por accidente, por ejemplo al escribir el nombre de un grupo nuevo. Cubre
// también los ejercicios de botones (sí/no, opciones, comparar) que no tienen ningún input
// donde colgar un listener propio.
document.addEventListener('keydown', e => {
  if(e.key !== 'Enter') return;
  if($('calcOv').style.display === 'flex') return;   // la calculadora ya maneja su propio Enter
  if(e.target && /^inP\d+$/.test(e.target.id || '')){   // Enter en un paso: al siguiente paso (o agrega uno), no avanza
    e.preventDefault(); const sig = $('inP' + (+e.target.id.slice(3) + 1)); if(sig) sig.focus(); else agregarPaso(); return;
  }
  // Enter en cualquier otra casilla de "Tu proceso" (fracciones, cajas de texto sueltas): pasa a la casilla
  // siguiente. Nunca salta de ejercicio — antes, después de "Ver explicación", te sacaba con lo escrito a medias.
  if(e.target && e.target.closest && e.target.closest('#zonaProceso')){
    e.preventDefault();
    const cs = [...document.querySelectorAll('#zonaProceso input.campo')], k = cs.indexOf(e.target);
    if(k >= 0 && cs[k + 1]) cs[k + 1].focus();
    return;
  }
  // Enter en una casilla de respuesta todavía sin contestar: comprueba (no pasa al siguiente)
  if(e.target && e.target.closest && e.target.closest('#zonaEntrada') && !respondido){ e.preventDefault(); responder(); return; }
  const btnSig = $('zonaFb') && $('zonaFb').querySelector('button.btn.amar');
  if(!btnSig) return;
  e.preventDefault();
  _siguienteEjercicio();
});

let _swReloadPendiente = false;   // ver el listener 'controllerchange' en ARRANQUE
function ir(pantalla, arg, continuar){
  // una versión nueva esperando se pone al cambiar de pantalla, pero NO al seguir practicando ("Siguiente"): recargar ahí te devolvía a la pregunta que acababas de contestar
  if(_swReloadPendiente && pantalla !== 'practica'){ window.location.reload(); return; }
  cerrarMenuGrupos();   // cambiar de pantalla no debe dejar la tarjeta flotando encima
  cerrarCalc();         // ni la calculadora abierta
  window.scrollTo(0,0);
  if(pantalla !== 'practica') borrarSesion();   // salir de la práctica = ronda terminada
  // salir de examen/errores sin terminar no debe dejar el modo "pegado" — si no, el modo
  // práctica normal queda contaminado (responder() y el botón "Siguiente" siguen esas reglas)
  if(pantalla !== 'examen'){ examen = null; clearInterval(_examenTimerIv); }
  if(pantalla !== 'errores') modoErrores = false;
  modoRepasoRonda = false;   // no hay pantalla dedicada — cualquier ir() cancela el repaso de la ronda
  // _pantallaActual solo debe apuntar a Inicio/Progreso mientras de verdad estás ahí — si no,
  // queda "pegado" ahí y un cambio remoto de sync te saca de la práctica solo, a media ronda
  // (bug real: pasaba en cualquier pantalla a la que entraras después de haber visto Inicio).
  if(pantalla !== 'inicio' && pantalla !== 'stats') _pantallaActual = null;
  if(pantalla === 'inicio')   return pantallaInicio();
  if(pantalla === 'temas')    return pantallaTemas();
  if(pantalla === 'practica') return nuevoEjercicio(arg, continuar);
  if(pantalla === 'stats')    return pantallaStats();
  if(pantalla === 'ajustes')  return pantallaAjustes();
  if(pantalla === 'tema')     return pantallaTema();
  if(pantalla === 'clase')    return pantallaClase();
  if(pantalla === 'elegir')   return pantallaElegirTemas();
  if(pantalla === 'grupos')   return pantallaGrupos();
  if(pantalla === 'sync')     return pantallaSync();
  if(pantalla === 'ia')       return pantallaIA();
  if(pantalla === 'examen')   return iniciarExamen(arg);
  if(pantalla === 'errores')  return pantallaErrores();
  if(pantalla === 'ayLeer')   return pantallaAyLeer(arg);
  if(pantalla === 'ayGaleria') return pantallaAyGaleria();
}

/* ══════════════════════════════════════════════════════════
   IA (Gemini) — OPCIONAL. Sin clave no se dibuja ningún botón de IA y la app queda igual.
   La IA solo EXPLICA, COMPARA y SUGIERE: nunca genera ejercicios, nunca decide si una respuesta
   está bien (eso es verificar()) y nunca toca stats/errores/racha. Todo lo que devuelve se valida
   aquí (ids de tema, número de paso). Cualquier ayuda de IA ANTES de contestar marca vioExpl:
   cuenta como "ver la explicación". Solo corre cuando se toca un botón (nada se gasta solo).
   ══════════════════════════════════════════════════════════ */
// SIN prefijo mate_ a propósito: exportarRespaldo() solo guarda mate_*, y la sync solo manda
// claves concretas — así la clave de la usuaria no va al .json ni a Firestore.
// La clave de IA tiene nombre propio por app: las cuatro apps (Fit-F, Fit-M, Mate, Facturas) viven en el mismo dominio y compartían
// 'ai_gemini_key_v1', así que pegar la clave en una pisaba la de las otras (y "Quitar" la quitaba en todas). La primera vez se copia la
// anterior, sin volver a pegarla; cuando las cuatro ya la copiaron, la vieja se borra. Sin prefijo fba_: no entra al backup.
const AI_KEY_STORAGE = 'ai_gemini_key_mate_v1';
(function () {
  try {
    const VIEJA = 'ai_gemini_key_v1', MARCA = 'ai_key_mig_mate';
    if (!localStorage.getItem(MARCA)) {
      const v = localStorage.getItem(VIEJA);
      if (v && !localStorage.getItem(AI_KEY_STORAGE)) localStorage.setItem(AI_KEY_STORAGE, v);
      localStorage.setItem(MARCA, '1');
    }
    if (['fitf', 'fitm', 'mate', 'fact'].every(a => localStorage.getItem('ai_key_mig_' + a))) localStorage.removeItem(VIEJA);
  } catch (e) {}
})();
const getAiKey = () => { try{ return localStorage.getItem(AI_KEY_STORAGE) || ''; }catch(e){ return ''; } };
// Del mejor al más básico: _aiJSON baja al siguiente si uno no está disponible. Con la clave
// gratis el Pro da 429 y los Flash 503 seguido; casi siempre responde Flash-Lite.
// (3.7-flash ya redirige a 3.8: era el mismo modelo dos veces; el de en medio es 3.6)
const AI_MODELS = ['gemini-3.1-pro-preview', 'gemini-3.8-flash', 'gemini-3.6-flash', 'gemini-3.5-flash-lite'];
const AI_SKIP_MS = 10 * 60 * 1000;                  // un modelo que falló se salta 10 min
const AI_SKIP_SINCUPO_MS = 24 * 60 * 60 * 1000;     // uno sin cupo gratis ("limit: 0", el Pro con la clave gratis) se salta 24 h
// Se recuerda entre aperturas (antes cada vez que abrías la app la primera pregunta volvía a probar el Pro, que da 429, y tardaba).
// Sin prefijo mate_ a propósito: no va al respaldo ni a la sincronización.
const AI_SKIP_KEY = 'ai_skip_mate_v1';
const _aiSkipUntil = (() => {
  const r = {};
  try{ const o = JSON.parse(localStorage.getItem(AI_SKIP_KEY) || '{}'), ahora = Date.now(); Object.keys(o).forEach(m => { if(AI_MODELS.includes(m) && o[m] > ahora) r[m] = o[m]; }); }catch(e){}
  return r;
})();
const _aiSkipGuardar = () => { try{ localStorage.setItem(AI_SKIP_KEY, JSON.stringify(_aiSkipUntil)); }catch(e){} };
const _aiSkipLimpiar = () => { Object.keys(_aiSkipUntil).forEach(m => delete _aiSkipUntil[m]); _aiSkipGuardar(); };
async function saveAiKey(){
  const inp = $('aiKeyInput'), key = (inp && inp.value || '').trim();
  if(!key){ if(inp) inp.focus(); return; }
  const btn = $('aiKeyBtn'); if(btn){ btn.disabled = true; btn.textContent = 'Probando…'; }
  let ok = null;   // null = sin señal para probarla
  try{
    // listar modelos no gasta cuota de generación
    const r = await fetch('https://generativelanguage.googleapis.com/v1beta/models?pageSize=1', { headers:{ 'x-goog-api-key': key }, signal: AbortSignal.timeout(8000) });
    ok = r.ok;
  }catch(e){}
  const volver = () => { if(btn){ btn.disabled = false; btn.textContent = 'Guardar'; } };
  if(ok === false){ $('zonaIAmsg').innerHTML = '<div class="fb mal">Esa clave no funciona — revísala.</div>'; return volver(); }
  try{ localStorage.setItem(AI_KEY_STORAGE, key); }
  catch(e){ $('zonaIAmsg').innerHTML = '<div class="fb mal">No se pudo guardar la clave en este aparato.</div>'; return volver(); }
  _aiSkipLimpiar();   // una clave nueva puede tener otro cupo
  pantallaIA();
  if(ok === null) $('zonaIAmsg').innerHTML = '<div class="fb medio">Clave guardada. Se probará cuando haya señal.</div>';
}
function clearAiKey(){
  confirmarAccion('¿Quitar la clave de IA? Los botones de IA se apagan en este aparato hasta que la pegues otra vez.', () => {
    try{ localStorage.removeItem(AI_KEY_STORAGE); }catch(e){}
    _aiSkipLimpiar();
    pantallaIA();
  });
}
// Una llamada a Gemini que devuelve JSON con la forma de `schema` (la API lo garantiza con
// responseSchema). Lanza un Error cuyo message es un aviso listo para mostrar.
async function _aiJSON(prompt, schema, extraParts){
  const key = getAiKey();
  if(!key) throw new Error('Primero pega tu clave en Ajustes → Inteligencia artificial');
  const body = JSON.stringify({
    contents: [{ parts: [{ text: prompt }, ...(extraParts || [])] }],
    generationConfig: { responseMimeType: 'application/json', responseSchema: schema }
  });
  let r;
  const now = Date.now();
  // el último (Flash-Lite, 500 al día gratis) NUNCA queda fuera por estar en pausa: así siempre hay a quién preguntarle
  const lista = AI_MODELS.filter((m, k) => k === AI_MODELS.length - 1 || !(_aiSkipUntil[m] > now));
  let reintentado = false, redReintentada = false;
  const cuotas = [];   // lo que dijo Google en cada 429, para saber si el límite es por minuto o por día
  for(let i = 0; i < lista.length; i++){
    const model = lista[i], ultimo = i === lista.length - 1;
    try{
      // 10 s por modelo (un 503 saturado llegó a tardar 13 s); el último espera 30 s
      r = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`, {
        method: 'POST',
        headers: { 'x-goog-api-key': key, 'Content-Type': 'application/json' },
        body,
        signal: AbortSignal.timeout(ultimo ? 30000 : 10000)
      });
    }catch(e){
      if(e.name === 'TimeoutError'){
        if(!ultimo){ _aiSkipUntil[model] = now + AI_SKIP_MS; continue; }
        throw new Error('La IA tardó demasiado — inténtalo de nuevo');
      }
      // Cualquier fallo de red cae aquí, no solo "sin internet": un microcorte al cambiar de wifi a datos
      // pasa en un segundo. Se reintenta una vez y se prueba el siguiente modelo antes de rendirse.
      if (!redReintentada) { redReintentada = true; i--; await new Promise(ok => setTimeout(ok, 1200)); continue; }
      if (!ultimo) continue;
      throw new Error(navigator.onLine === false ? 'Sin señal — inténtalo cuando tengas internet' : 'No se pudo conectar con la IA — inténtalo de nuevo');
    }
    // el último no tiene a cuál pasar: un 500/503 suele ser un pico de un segundo, se reintenta una vez
    if(ultimo && [500, 503].includes(r.status) && !reintentado){ reintentado = true; i--; await new Promise(ok => setTimeout(ok, 1500)); continue; }
    if(![404, 429, 500, 503].includes(r.status)) break;
    let sinCupo = false;
    if(r.status === 429){
      let t = ''; try{ t = JSON.stringify((await r.json()).error || {}); }catch(e){}
      cuotas.push(t); sinCupo = /limit:\s*0\b/.test(t);
    }
    _aiSkipUntil[model] = now + (sinCupo ? AI_SKIP_SINCUPO_MS : AI_SKIP_MS);
    _aiSkipGuardar();
  }
  if(r.status === 429){
    // un 429 puede ser "muchas seguidas" (por minuto) o "se acabó el día"; un modelo sin cupo ("limit: 0") no cuenta como límite tuyo
    const real = cuotas.filter(t => !/limit:\s*0\b/.test(t));
    if(real.some(t => /PerDay|per day|daily/i.test(t))) throw new Error('Llegaste al límite gratis de la IA por hoy — mañana vuelve a funcionar');
    if(real.some(t => /PerMinute|per minute/i.test(t))) throw new Error('Mandaste muchas preguntas seguidas — espera un minuto e inténtalo de nuevo');
    throw new Error('Ningún modelo gratis pudo contestar ahora (no es tu límite del día) — inténtalo en unos minutos');
  }
  if(!r.ok){
    // un 400 también sale por una foto que Google no puede leer — solo es culpa de la clave si el mensaje lo dice
    const err = await r.json().catch(() => ({}));
    const msg = JSON.stringify(err.error || {});
    if(r.status === 401 || r.status === 403 || /API.?key|API_KEY/i.test(msg)) throw new Error('La clave de IA no funciona — revísala en Ajustes');
    throw new Error(r.status === 400 ? 'La IA no pudo con eso — prueba con otra foto o texto' : 'La IA no respondió — inténtalo de nuevo');
  }
  const d = await r.json();
  const txt = (d.candidates?.[0]?.content?.parts || []).filter(p => !p.thought).map(p => p.text || '').join('');
  try{ return JSON.parse(txt); }
  catch(e){ throw new Error('La IA no respondió bien — inténtalo de nuevo'); }
}
// Foto → { mime, data } en base64, achicada (una foto del teléfono pesa varios MB). Fondo blanco:
// un PNG transparente pasado a JPEG sale con fondo NEGRO y la letra negra desaparece.
async function _imgParaIA(file, max){
  max = max || 1024;
  try{
    const bmp = await createImageBitmap(file);
    const k = Math.min(1, max / Math.max(bmp.width, bmp.height));
    const c = document.createElement('canvas');
    c.width = Math.round(bmp.width * k); c.height = Math.round(bmp.height * k);
    const ctx = c.getContext('2d');
    ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, c.width, c.height);
    ctx.drawImage(bmp, 0, 0, c.width, c.height);
    return { mime: 'image/jpeg', data: c.toDataURL('image/jpeg', 0.82).split(',')[1] };
  }catch(e){
    const data = await new Promise((ok, fail) => { const fr = new FileReader(); fr.onload = () => ok(String(fr.result).split(',')[1]); fr.onerror = fail; fr.readAsDataURL(file); });
    return { mime: file.type || 'image/jpeg', data };
  }
}
function pantallaIA(){
  _barra('ajustes');
  const tiene = !!getAiKey();
  main.innerHTML = `
    <button class="back" onclick="ir('ajustes')">← Ajustes</button>
    <div class="card">
      <h2>Inteligencia artificial</h2>
      <p style="font-size:.93rem;color:var(--muted);margin-bottom:12px">Opcional y gratis. Pega tu clave de Google (Gemini) y aparecen los botones de IA. La clave se queda solo en este aparato: no va al respaldo ni a la sincronización.</p>
      ${tiene ? `<div class="fb ok">IA conectada</div>
        <button class="btn sec" onclick="clearAiKey()">Quitar la clave</button>`
      : `<input class="campo" id="aiKeyInput" type="password" autocomplete="off" autocapitalize="off" placeholder="Pega tu clave aquí">
        <button class="btn amar" id="aiKeyBtn" style="margin-top:10px" onclick="saveAiKey()">Guardar</button>`}
      <div id="zonaIAmsg"></div>
      ${tiene ? '' : `<div class="nota">La sacas en <b>aistudio.google.com/apikey</b> con tu cuenta de Google → "Crear clave de API".</div>`}
    </div>
    ${tiene ? `<div class="card">
      <h2>Qué hace la IA aquí</h2>
      <div class="nota" style="margin:0 0 8px">Toca la burbuja <b>AI</b> y se abre un chat. <b>En cada ejercicio</b>: revisa tu proceso (también con una foto de tu cuaderno), te lo explica de otra forma o te da una pista.</div>
      <div class="nota" style="margin:0 0 8px"><b>Foto de mi tarea</b> (en Inicio): te dice qué tema es y te da una pista, no la solución.</div>
      <div class="nota" style="margin:0 0 8px"><b>Plan de repaso</b> (en Progreso) y <b>tu ronda</b> (al terminarla): chatea con tus datos reales.</div>
      <div class="nota" style="margin:0">La IA solo explica: nunca decide si tu respuesta está bien, eso lo hace la app. Pedir ayuda a la IA antes de contestar cuenta como ver la explicación, y ese ejercicio no suma a tus estadísticas. Puede equivocarse: úsala como apoyo.</div>
    </div>` : ''}`;
}

/* ---------- IA: textos que se le mandan (sin HTML, sin dibujos) ---------- */
const _aiTxt = h => String(h == null ? '' : h).replace(/<svg[\s\S]*?<\/svg>/g, ' ').replace(/<br\s*\/?>/g, '\n').replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&').replace(/[ \t]+/g, ' ').replace(/\n\s+/g, '\n').trim();
// la explicación (con sus marcas §paso|…) en texto plano
function _aiExplTxt(lista){
  const rot = { paso:'', resp:'Respuesta: ', comp:'Comprobación: ', error:'Error común: ', pide:'Qué te piden: ' };
  return (lista || []).map(l => typeof l === 'string' ? _aiTxt(l.replace(/^§(\w+)\|/, (m, k) => rot[k] !== undefined ? rot[k] : '')) : '').filter(Boolean).join('\n').slice(0, 5000);
}
// lo que ella escribió en "Tu proceso": las fracciones ⟦arriba|abajo⟧ y a/b = c/d pasan a texto
const _aiProcesoTxt = s => String(s || '').replace(/⟪([^|⟫]*)\|([^|⟫]*)\|([^|⟫]*)\|([^|⟫]*)\|[^⟫]*⟫/g, '($1)/($2) = ($3)/($4)').replace(/⟦([^|⟧]*)\|([^⟧]*)⟧/g, '($1)/($2)');
// su respuesta, según el tipo de ejercicio
function _aiRespTxt(ej, ent){
  try{
    if(ent == null || ent === '') return '(no respondió)';
    const plano = typeof ent === 'object' ? Object.values(ent).map(v => typeof v === 'object' ? JSON.stringify(v) : v).join('') : String(ent);
    if(!/[\p{L}\p{N}]/u.test(plano)) return '(no respondió todavía)';   // casillas vacías: ["",""] / {a:"",b:""}
    switch(ej.tipo){
      case 'sino': return ent ? 'Sí' : 'No';
      case 'cmp': case 'opciones': case 'num': case 'texto': return _aiTxt(ent);
      case 'frac': return `${ent.n}/${ent.d}`;
      case 'mixto': return `${ent.e} ${ent.n}/${ent.d}`;
      case 'orden': return ent.map(i => _aiTxt(_ordenTexto(ej.opciones[i]))).join(' , ');
      case 'angulo2': return `${ent.a}, ${ent.b}`;
      case 'basexp': return `Base = ${ent.b}, Exponente = ${ent.e}, Valor = ${ent.v}`;
      case 'coefvar': return `Coeficiente = ${ent.coef}, Variable = ${ent.variable}`;
      case 'multi': return ej.campos.map((c, i) => `${c.et}: ${ent[i]}${c.fs && ent.f && ent.f[i] ? ' (fórmula escrita: ' + ent.f[i] + ')' : ''}`).join('; ');
    }
  }catch(e){}
  return _aiTxt(JSON.stringify(ent));
}
const _aiEjTxt = ej => ({
  enunciado: _aiTxt(ej.enunciado) + (/<svg/.test(String(ej.enunciado)) ? '\n(El ejercicio trae un dibujo que no puedes ver.)' : ''),
  correcta: _aiTxt(fmtRespuesta(ej)),
  oficial: _aiExplTxt(ej.explicacion)
});
const _aiTutor = () => 'Eres una tutora paciente de «' + MATERIAS[materia].nombre + '» para una estudiante universitaria que practica en una app. ' +
  'Hablas en español, tuteando, claro, directo y alentador, sin emojis ni markdown. La app ya calcula y verifica las respuestas: ' +
  'tú NO decides qué es correcto, NO recalcules de nuevo ni discutas la respuesta correcta que se te da. ' +
  'Usa SOLO los datos del ejercicio y de la explicación oficial; no agregues datos externos ni inventes. Si no estás segura de algo, dilo.\n\n';

/* ---------- IA: burbuja AI → chat (una conversación por función) ---------- */
// aviso corto (no había uno en Mate)
function showToast(msg) {
  const t = document.createElement('div');
  t.textContent = msg; t.setAttribute('role', 'status');
  t.style.cssText = 'position:fixed;left:50%;bottom:90px;transform:translateX(-50%);max-width:86vw;padding:10px 16px;border-radius:14px;background:rgba(30,30,34,.94);color:#fff;font-size:.9rem;z-index:1400;text-align:center';
  document.body.appendChild(t); setTimeout(() => t.remove(), 2600);
}
// Dictado por voz del navegador (Web Speech API) — no usa la IA ni la clave.
// Android Chrome y Safari lo traen; donde no existe, el botón no se muestra.
const _MIC_SVG = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10a7 7 0 0 0 14 0M12 17v5"/></svg>';
function _dictadoDisponible() {
  return !!(window.SpeechRecognition || window.webkitSpeechRecognition);
}
// Dictado tipo INTERRUPTOR: un toque en el micrófono empieza a escuchar (el texto va apareciendo en el campo) y otro toque en el mismo
// micrófono lo apaga. Al apagarse, si se entendió algo, llama onText(texto). Si se corta solo (silencio) mientras sigue encendido, se
// vuelve a encender; otro micrófono encendido se apaga. El botón `btnId` se pinta mientras escucha.
let _dictando = null;   // { rec, btnId, activo, sinCb, dicho }
function _dictarParar(sinCb) {   // apagar el que esté escuchando (sinCb = no llamar onText: se va a enviar o cerrar por otro lado)
  const d = _dictando; if (!d) return;
  d.activo = false; if (sinCb) d.sinCb = true;
  try { d.rec.stop(); } catch (e) {}
}
function _dictar(inputId, btnId, onText) {
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  const inp = document.getElementById(inputId), btn = document.getElementById(btnId);
  if (!SR || !inp) return;
  if (_dictando && _dictando.btnId === btnId) { _dictarParar(); return; }   // segundo toque: apagar
  if (_dictando) _dictarParar(true);                                          // otro micrófono encendido: se apaga
  const st = { rec: null, btnId, activo: true, sinCb: false, dicho: false };
  _dictando = st;
  const base = inp.value.trim() ? inp.value.trim() + ' ' : '';   // lo que ya estaba escrito se conserva
  let finales = '', t0 = 0;
  const bgAntes = btn ? btn.style.background : '', phAntes = inp.placeholder;
  if (btn) { btn.style.background = 'rgba(74,222,128,.35)'; btn.setAttribute('aria-pressed', 'true'); }
  inp.placeholder = 'Te escucho… toca el micrófono para terminar';
  const cerrar = () => {
    if (btn && btn.isConnected) { btn.style.background = bgAntes; btn.setAttribute('aria-pressed', 'false'); }
    if (inp.isConnected) inp.placeholder = phAntes; // cada campo vuelve a SU texto de ayuda
    if (_dictando === st) _dictando = null;
    const txt = inp.value.trim();
    if (st.dicho && !st.sinCb && onText && txt) onText(txt);
  };
  const arrancar = () => {
    const rec = new SR();
    st.rec = rec; t0 = Date.now();
    rec.lang = 'es-US';
    rec.continuous = true;
    rec.interimResults = true;
    rec.maxAlternatives = 1;
    rec.onresult = e => {
      let prov = '';
      for (let i = e.resultIndex; i < e.results.length; i++) {
        const t = e.results[i][0].transcript;
        if (e.results[i].isFinal) finales += (finales ? ' ' : '') + t.trim(); else prov += t;
      }
      const txt = (base + finales + (prov ? (finales ? ' ' : '') + prov.trim() : '')).trim();
      if (txt) { inp.value = txt; st.dicho = true; }
    };
    rec.onerror = e => {
      if (e.error === 'not-allowed' || e.error === 'service-not-allowed') { st.activo = false; showToast('Permite el micrófono para dictar'); }
      else if (e.error !== 'no-speech' && e.error !== 'aborted') { st.activo = false; showToast('No se pudo dictar'); }
    };
    rec.onend = () => {
      // se cortó solo (silencio) pero sigue encendido: se vuelve a encender (si no falló al instante, para no quedar en un ciclo)
      if (st.activo && Date.now() - t0 > 800) { try { arrancar(); return; } catch (e) {} }
      cerrar();
    };
    try { rec.start(); } catch (e) { cerrar(); }
  };
  arrancar();
}
