/* ---------- temas: tema suelto, elegir para mezclar, grupos de examen ---------- */
// Repaso de ayudante y Álgebra: las casillas de la lista de Temas deciden qué entra en la "Mezcla" de SU capítulo
// (sin nada marcado en el capítulo, la mezcla trae todo, como siempre). Se guarda en mate_seltemas_v1.
let selTemas = (leer('mate_seltemas_v1', []) || []).filter(id => MOD_POR_ID[id]);
const _conCasillas = () => materia === 'ayud' || materia === 'mate';
const _modsCap = cap => MODULOS.filter(m => m.clase === materia && m.secciones[0][0] === String(cap));
function _mezclaTexto(cap){
  const ms = _modsCap(cap), total = tamanoMezcla(ms.filter(m => !m.extra));
  const sel = _conCasillas() ? ms.filter(m => selTemas.includes(m.id)) : [];
  if(!sel.length) return `${total} preguntas`;
  const n = tamanoMezcla(sel);
  return n <= total ? `${n}/${total} preguntas` : `${n} preguntas`;   // un tema Extra marcado puede pasar del total de la mezcla normal
}
function toggleSelTema(id, on){
  const i = selTemas.indexOf(id);
  if(on && i < 0) selTemas.push(id);
  if(!on && i >= 0) selTemas.splice(i, 1);
  guardar('mate_seltemas_v1', selTemas);
  const cap = MOD_POR_ID[id].secciones[0][0], el = $('mzl_' + cap); if(el) el.textContent = _mezclaTexto(cap);
}
function pantallaTemas(){
  _barra('temas');
  main.innerHTML = `
    ${ayudMaterialHTML()}
    <div class="card">
      <h2>Practicar un tema suelto</h2>
      ${materia === 'mate' ? '<div class="nota"><b>Se repite</b> = el mismo tema con otros ejercicios: uno al azar y otro con las preguntas exactas de tu Tarea y tus Quizzes de EducoSoft (mismo color). La casilla mete el tema en la mezcla de su capítulo; los de EducoSoft solo entran si los marcas.</div>' : ''}
      ${MATERIAS[materia].caps.map(cap => { const ms = MODULOS.filter(m=>m.clase===materia && m.secciones[0][0]===String(cap)); return `
        <details class="temaCap">
          <summary>${nombreCapitulo(cap)}</summary>
          <button class="btn amar chico" onclick="ir('practica',${cap})">Mezcla de ${nombreCapitulo(cap).replace(/^Capítulo /,'capítulo ')}
            <small id="mzl_${cap}">${_mezclaTexto(cap)}</small></button>
          ${ms.map(m=>{
            const s = stats[m.id], p = s ? pct(s) : null;
            const btnTema = `<button class="btn sec chico${m.tag ? ' conTag' : ''}" onclick="ir('practica','${m.id}')">${m.nombre}${ayTagHTML(m)}
              ${_otroLado(m) ? `<small>${_otroLado(m)}</small>` : ''}${p!==null ? `<small>${p}% de aciertos · ${s.ok+s.fallo} ejercicios</small>` : ''}</button>`;
            return (_conCasillas() ? `<div class="temaFila"><input type="checkbox" aria-label="Marcar ${escHtml(m.nombre)}" ${selTemas.includes(m.id) ? 'checked' : ''} onchange="toggleSelTema('${m.id}', this.checked)">${btnTema}</div>` : btnTema) +
              (m.nuevaRonda && !m.sinReloj ? `<button class="btn sec chico" onclick="ir('examen','${m.id}')">${_nombreSimulacro(m)} con reloj
                <small>las ${m.banco} preguntas en 1 h 30 min, como el examen real, con la nota al final</small></button>` : '');
          }).join('')}
        </details>`; }).join('')}
    </div>

    <div class="card">
      <button class="btn" onclick="ir('elegir')">Elegir temas para mezclar
        <small>combina los que quieras, por ejemplo ${nombreCapitulo(MATERIAS[materia].caps[0]).toLowerCase()} con ${nombreCapitulo(MATERIAS[materia].caps[1]||MATERIAS[materia].caps[0]).toLowerCase()}</small></button>
      <button class="btn" onclick="ir('grupos')">Grupos de examen
        <small>${gruposMateria().length ? `${gruposMateria().length} guardado${gruposMateria().length===1?'':'s'} — junta capítulos y ponles nombre` : 'junta capítulos o temas y ponles nombre, ej. "Examen 1"'}</small></button>
    </div>`;
}

